// Generated by tools/text-index.mjs (do not edit): every plain text line of the game and where it is said.
export const TEXT_INDEX = [{"text":"¡Eh, vos! ¿Qué mirás?","uses":[{"file":"data/amistad.ts","line":40,"ctx":"ramon_recluta","who":""}]},{"text":"Estas bolsas son residuo de la máquina de niebla. Las vacío en este campo y nadie se entera.","uses":[{"file":"data/amistad.ts","line":42,"ctx":"ramon_recluta","who":""}]},{"text":"Y si lo vas a andar contando por ahí, primero me tenés que ganar.","uses":[{"file":"data/amistad.ts","line":42,"ctx":"ramon_recluta","who":""}]},{"text":"¿Otra vez vos? Las bolsas no se vacían solas.","uses":[{"file":"data/amistad.ts","line":45,"ctx":"ramon_recluta","who":""}]},{"text":"Volvé cuando tus criaturas estén listas.","uses":[{"file":"data/amistad.ts","line":50,"ctx":"ramon_recluta","who":""}]},{"text":"Esto no queda así. La jefa se va a enterar.","uses":[{"file":"data/amistad.ts","line":51,"ctx":"ramon_recluta","who":""}]},{"text":"Vi todo desde el alambrado. Gracias, de verdad.","uses":[{"file":"data/amistad.ts","line":55,"ctx":"ramon_recluta","who":""}]},{"text":"Ese residuo quema el pasto. Con una lluvia encima, el arroyo se lo llevaba a todos los campos de la zona.","uses":[{"file":"data/amistad.ts","line":55,"ctx":"ramon_recluta","who":""}]},{"text":"Me llamo Ramón. Ando recorriendo campos, viendo cómo le pega la niebla al ganado. Digamos que trabajo para el campo.","uses":[{"file":"data/amistad.ts","line":56,"ctx":"ramon_recluta","who":"Ramón"}]},{"text":"¿Y vos cómo te llamás?","uses":[{"file":"data/amistad.ts","line":56,"ctx":"ramon_recluta","who":"Ramón"},{"file":"data/amistad.ts","line":76,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Le decís tu nombre.","uses":[{"file":"data/amistad.ts","line":57,"ctx":"ramon_recluta","who":""},{"file":"data/amistad.ts","line":77,"ctx":"ramon_paso","who":""}]},{"text":"{player}. Me lo voy a acordar.","uses":[{"file":"data/amistad.ts","line":58,"ctx":"ramon_recluta","who":"Ramón"},{"file":"data/amistad.ts","line":78,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Yo sigo para Rivera: tengo una reunión con gente del gobierno. Un aburrimiento, pero hay que ir.","uses":[{"file":"data/amistad.ts","line":58,"ctx":"ramon_recluta","who":"Ramón"}]},{"text":"Tomá, que no sea nada. Para el camino.","uses":[{"file":"data/amistad.ts","line":58,"ctx":"ramon_recluta","who":"Ramón"}]},{"text":"Ojalá nos volvamos a cruzar. Cuidate.","uses":[{"file":"data/amistad.ts","line":60,"ctx":"ramon_recluta","who":"Ramón"}]},{"text":"¡{player}! ¡Qué casualidad encontrarte acá!","uses":[{"file":"data/amistad.ts","line":70,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Buenas. ¿Venís de Rivera? Se te nota en las botas: el polvo colorado de allá no se va con nada.","uses":[{"file":"data/amistad.ts","line":75,"ctx":"ramon_paso","who":""}]},{"text":"Me llamo Ramón. Recorro los campos viendo cómo le pega la niebla al ganado.","uses":[{"file":"data/amistad.ts","line":76,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Vengo de ver los arroyos. Están bajos y con una espuma gris que no me gusta nada.","uses":[{"file":"data/amistad.ts","line":80,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Yo voy para Tacuarembó, que allá tengo… bueno, mi trabajo. Cuando llegues, te invito un mate. Prometido.","uses":[{"file":"data/amistad.ts","line":80,"ctx":"ramon_paso","who":"Ramón"}]},{"text":"Gracias otra vez.","uses":[{"file":"data/amistad.ts","line":96,"ctx":"Persona (Ramón, aspecto leader_mgap)","who":"Ramón"}]},{"text":"Nos vemos en Tacuarembó.","uses":[{"file":"data/amistad.ts","line":103,"ctx":"Persona (Ramón, aspecto leader_mgap)","who":"Ramón"}]},{"text":"Ya pasaste mi examen. Colonia tiene más historia de la que cabe en una tarde.","uses":[{"file":"data/events.ts","line":70,"ctx":"ev_quiz","who":""}]},{"text":"Correcto.","uses":[{"file":"data/events.ts","line":81,"ctx":"ev_quiz","who":""}]},{"text":"No exactamente.","uses":[{"file":"data/events.ts","line":81,"ctx":"ev_quiz","who":""}]},{"text":"Ganaste el verso y yo perdí la voz. Pasa que la tradición manda.","uses":[{"file":"data/events.ts","line":98,"ctx":"ev_payada","who":""}]},{"text":"Cantás mejor que lo que decís. Llevate esto de recuerdo.","uses":[{"file":"data/events.ts","line":115,"ctx":"ev_payada","who":""}]},{"text":"Todavía te falta cancha, pero hay que animarse. Tomá un mate.","uses":[{"file":"data/events.ts","line":119,"ctx":"ev_payada","who":""}]},{"text":"El torneo del Club de Remo ya lo ganaste. Siempre hay otra regata, pero esa copa es tuya.","uses":[{"file":"data/events.ts","line":127,"ctx":"ev_torneo","who":""}]},{"text":"Torneo relámpago del Club de Remo: tres combates seguidos, sin curar entre uno y otro.","uses":[{"file":"data/events.ts","line":128,"ctx":"ev_torneo","who":""}]},{"text":"Si ganás los tres, te llevás una criatura del club como premio. Si perdés, podés volver a intentar.","uses":[{"file":"data/events.ts","line":128,"ctx":"ev_torneo","who":""}]},{"text":"Quedaste eliminado, pero atendimos a tus criaturas. Volvé cuando quieras.","uses":[{"file":"data/events.ts","line":142,"ctx":"ev_torneo","who":""}]},{"text":"¡Campeón del torneo relámpago!","uses":[{"file":"data/events.ts","line":147,"ctx":"ev_torneo","who":""}]},{"text":"El club te regala una criatura criada en la costanera.","uses":[{"file":"data/events.ts","line":147,"ctx":"ev_torneo","who":""}]},{"text":"Gracias por el trato. Lo cuido como si fuera mío.","uses":[{"file":"data/events.ts","line":158,"ctx":"ev_trueque","who":""}]},{"text":"Cuando tengas uno, volvé.","uses":[{"file":"data/events.ts","line":161,"ctx":"ev_trueque","who":""}]},{"text":"Gracias por ayudarme a cerrar esa historia. El mar guarda las otras.","uses":[{"file":"data/events.ts","line":175,"ctx":"ev_buscatesoros","who":""}]},{"text":"Dicen que un marinero escondió una caja cerca de la costa hace cien años.","uses":[{"file":"data/events.ts","line":177,"ctx":"ev_buscatesoros","who":""}]},{"text":"Los que saben algo andan por el pueblo. Todos recuerdan un pedacito distinto.","uses":[{"file":"data/events.ts","line":177,"ctx":"ev_buscatesoros","who":""}]},{"text":"Seguí preguntando por el pueblo.","uses":[{"file":"data/events.ts","line":178,"ctx":"ev_buscatesoros","who":""}]},{"text":"Un faro, tres palmeras y la sombra del mediodía… ¡Todo cuadra!","uses":[{"file":"data/events.ts","line":179,"ctx":"ev_buscatesoros","who":""}]},{"text":"¿Vamos a cavar juntos?","uses":[{"file":"data/events.ts","line":179,"ctx":"ev_buscatesoros","who":""}]},{"text":"Cavamos un buen rato. La caja estaba ahí, tal cual la describieron.","uses":[{"file":"data/events.ts","line":182,"ctx":"ev_buscatesoros","who":""}]},{"text":"El concurso de este año ya se juzgó. El parque queda para los paseos.","uses":[{"file":"data/events.ts","line":195,"ctx":"ev_concurso","who":""}]},{"text":"Tiempo cumplido. Vamos a juzgar lo que trajiste.","uses":[{"file":"data/events.ts","line":199,"ctx":"ev_concurso","who":""}]},{"text":"No atrapaste nada, así que no hay nada que juzgar. Gracias por participar.","uses":[{"file":"data/events.ts","line":202,"ctx":"ev_concurso","who":""}]},{"text":"Elegí la criatura que presentás. Es la que te quedás; las demás vuelven al parque.","uses":[{"file":"data/events.ts","line":205,"ctx":"ev_concurso","who":""}]},{"text":"Resultados:","uses":[{"file":"data/events.ts","line":213,"ctx":"ev_concurso","who":""},{"file":"data/events.ts","line":297,"ctx":"ev_pesca","who":""}]},{"text":"¡Primer puesto!","uses":[{"file":"data/events.ts","line":217,"ctx":"ev_concurso","who":""}]},{"text":"Segundo puesto. Muy bien.","uses":[{"file":"data/events.ts","line":218,"ctx":"ev_concurso","who":""}]},{"text":"Tercer puesto.","uses":[{"file":"data/events.ts","line":219,"ctx":"ev_concurso","who":""}]},{"text":"Quedaste cuarto, pero participar suma. Una compensación.","uses":[{"file":"data/events.ts","line":220,"ctx":"ev_concurso","who":""}]},{"text":"Concurso de captura del Parque de Canelones: una sola participación.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Te damos 20 balls del parque y 8 minutos. Atrapá criaturas dentro del parque; al final elegís una y los jueces la puntúan.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Se puntúa el nivel, lo rara que es, sus características y cuánta salud conserva al atraparla.","uses":[{"file":"data/events.ts","line":224,"ctx":"ev_concurso","who":""}]},{"text":"Suerte. Cuando suene la campana, volvé a verme.","uses":[{"file":"data/events.ts","line":229,"ctx":"ev_concurso","who":""}]},{"text":"Te acompaño a la salida.","uses":[{"file":"data/events.ts","line":235,"ctx":"ev_concurso_salida","who":"Guardaparque"}]},{"text":"Ya me ganaste mis tres acertijos. Se me acabaron los buenos.","uses":[{"file":"data/events.ts","line":245,"ctx":"ev_adivino","who":""}]},{"text":"Hago tres preguntas y no perdono ninguna.","uses":[{"file":"data/events.ts","line":246,"ctx":"ev_adivino","who":""}]},{"text":"Si respondés bien las tres seguidas, hay premio. Si fallás una, empezamos de nuevo.","uses":[{"file":"data/events.ts","line":246,"ctx":"ev_adivino","who":""}]},{"text":"No es eso. Pensalo mejor y volvé a empezar.","uses":[{"file":"data/events.ts","line":254,"ctx":"ev_adivino","who":""}]},{"text":"Las tres. Hacía años que nadie me ganaba.","uses":[{"file":"data/events.ts","line":259,"ctx":"ev_adivino","who":""}]},{"text":"El concurso de este año ya tiene ganador: vos. Gracias por participar.","uses":[{"file":"data/events.ts","line":268,"ctx":"ev_pesca","who":""}]},{"text":"Concurso de pesca del río. Hace falta una caña para anotarse. El pescador de la playa regala una vieja.","uses":[{"file":"data/events.ts","line":271,"ctx":"ev_pesca","who":""}]},{"text":"Concurso de pesca del Uruguay: una sola participación, 5 minutos de reloj.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Pescá desde el muelle: parate frente al agua y apretá A. Cada pez que saques queda registrado.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Al final, o cuando quieras entregar, volvé conmigo y elegí el mejor. Se puntúa nivel, rareza, características y estado.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"Lo que saques depende de tu caña: la vieja solo trae lo más común.","uses":[{"file":"data/events.ts","line":272,"ctx":"ev_pesca","who":""}]},{"text":"¡Empieza el reloj! Pescá todo lo que puedas.","uses":[{"file":"data/events.ts","line":276,"ctx":"ev_pesca","who":""}]},{"text":"¡Tiempo! Veamos qué sacaste.","uses":[{"file":"data/events.ts","line":283,"ctx":"ev_pesca","who":""}]},{"text":"No sacaste nada, así que no hay nada que juzgar. Podés anotarte otra vez cuando quieras.","uses":[{"file":"data/events.ts","line":286,"ctx":"ev_pesca","who":""}]},{"text":"Elegí el pez que presentás. Es el que te quedás; los demás vuelven al río.","uses":[{"file":"data/events.ts","line":289,"ctx":"ev_pesca","who":""}]},{"text":"La carrera ya la ganaste. El récord de la ciclovía sigue siendo tuyo.","uses":[{"file":"data/events.ts","line":314,"ctx":"ev_carrera_juez","who":""}]},{"text":"Esto es una carrera de bicicletas. Sin bici no se larga.","uses":[{"file":"data/events.ts","line":315,"ctx":"ev_carrera_juez","who":""}]},{"text":"Se te fue el tiempo. El límite es de 24 segundos. Podés largar de nuevo cuando quieras.","uses":[{"file":"data/events.ts","line":320,"ctx":"ev_carrera_juez","who":""}]},{"text":"Es un tiempo de campeonato. Medalla de oro.","uses":[{"file":"data/events.ts","line":323,"ctx":"ev_carrera_juez","who":""}]},{"text":"Muy buen tiempo. Medalla de plata.","uses":[{"file":"data/events.ts","line":324,"ctx":"ev_carrera_juez","who":""}]},{"text":"Llegaste dentro del límite. Medalla de bronce.","uses":[{"file":"data/events.ts","line":325,"ctx":"ev_carrera_juez","who":""}]},{"text":"Carrera de ida y vuelta por la Ciclovía: hasta el cronometrista del final y de regreso acá.","uses":[{"file":"data/events.ts","line":328,"ctx":"ev_carrera_juez","who":""}]},{"text":"El límite son 24 segundos. Los ciclistas del camino tienen que haber quedado atrás: si te cruzan, te frenan.","uses":[{"file":"data/events.ts","line":328,"ctx":"ev_carrera_juez","who":""}]},{"text":"Preparados… ¡Ya!","uses":[{"file":"data/events.ts","line":331,"ctx":"ev_carrera_juez","who":""}]},{"text":"Qué carrera. Todavía se comenta.","uses":[{"file":"data/events.ts","line":336,"ctx":"ev_carrera_meta","who":""}]},{"text":"Acá termina la Ciclovía. El que organiza las carreras está en la largada, al sur.","uses":[{"file":"data/events.ts","line":337,"ctx":"ev_carrera_meta","who":""}]},{"text":"Llegaste tarde: ya pasó el tiempo límite. Volvé a largar desde el sur.","uses":[{"file":"data/events.ts","line":339,"ctx":"ev_carrera_meta","who":""}]},{"text":"Mi abuelo contaba que la caja del marinero estaba a la vista del faro, pero que nadie la vio nunca de día.","uses":[{"file":"data/events.ts","line":359,"ctx":"Persona (Pescador, aspecto sailor, evento ev_pista)","who":"Pescador"}]},{"text":"Tres palmeras había en la punta, decía mi madre. Hoy queda solo una, la más chica.","uses":[{"file":"data/events.ts","line":360,"ctx":"Persona (Abuela del almacén, aspecto oldman, evento ev_pista)","who":"Abuela del almacén"}]},{"text":"A mediodía la sombra de la palmera señala hacia el mar. Mi tío dice que ahí hay que cavar.","uses":[{"file":"data/events.ts","line":361,"ctx":"Persona (Nene, aspecto nino, evento ev_pista)","who":"Nene"}]},{"text":"Hay sortija, jineteada y taba, con premios para los que se animen. También hay música, fogones y tortas fritas.","uses":[{"file":"data/fiesta.ts","line":50,"ctx":"fg_intro","who":""}]},{"text":"Cuando se termine el segundo día levantamos todo, así que no te duermas.","uses":[{"file":"data/fiesta.ts","line":50,"ctx":"fg_intro","who":""}]},{"text":"La sortija y la taba se juegan cada día. La jineteada da su premio mayor una sola vez.","uses":[{"file":"data/fiesta.ts","line":63,"ctx":"fg_comision","who":""}]},{"text":"Hoy ya te llevaste tu garrapiñada. Si mañana sigue la fiesta, volvé a correr.","uses":[{"file":"data/fiesta.ts","line":73,"ctx":"fg_sortija","who":""}]},{"text":"La sortija: pasás al galope bajo el arco y tenés que enganchar la argolla con la vara.","uses":[{"file":"data/fiesta.ts","line":74,"ctx":"fg_sortija","who":""}]},{"text":"Son tres pasadas, cada una más rápida. Si sacás las tres, la garrapiñada es tuya.","uses":[{"file":"data/fiesta.ts","line":74,"ctx":"fg_sortija","who":""}]},{"text":"¡Las tres argollas! Hacía rato que no se veía una carrera así.","uses":[{"file":"data/fiesta.ts","line":80,"ctx":"fg_sortija","who":""}]},{"text":"No enganchaste ninguna. Mirá la argolla, no al caballo. Podés volver a correr.","uses":[{"file":"data/fiesta.ts","line":85,"ctx":"fg_sortija","who":""}]},{"text":"Por hoy ya fue suficiente. El potro también tiene que descansar.","uses":[{"file":"data/fiesta.ts","line":94,"ctx":"fg_jineteada","who":""}]},{"text":"Al suelo. Le pasa a los mejores. Sacudite el polvo y probá de nuevo cuando quieras.","uses":[{"file":"data/fiesta.ts","line":100,"ctx":"fg_jineteada","who":""}]},{"text":"¡Aguantó hasta la campana! La tropilla cumple su palabra.","uses":[{"file":"data/fiesta.ts","line":105,"ctx":"fg_jineteada","who":""}]},{"text":"¡Otra vez arriba hasta el final! Tomá, te la ganaste.","uses":[{"file":"data/fiesta.ts","line":109,"ctx":"fg_jineteada","who":""}]},{"text":"Ya te llevaste tres premios hoy. Dejá algo para los demás.","uses":[{"file":"data/fiesta.ts","line":119,"ctx":"fg_taba","who":""}]},{"text":"La taba: la tirás al hoyo y, si cae de suerte, ganás. Si cae de culo, perdés.","uses":[{"file":"data/fiesta.ts","line":120,"ctx":"fg_taba","who":""}]},{"text":"Tres premios en un día. La taba te quiere.","uses":[{"file":"data/fiesta.ts","line":122,"ctx":"fg_taba","who":""}]},{"text":"No te alcanza la plata para la tirada.","uses":[{"file":"data/fiesta.ts","line":124,"ctx":"fg_taba","who":""}]},{"text":"¡Suerte! La taba cayó parada del lado bueno.","uses":[{"file":"data/fiesta.ts","line":131,"ctx":"fg_taba","who":""}]},{"text":"Culo. Cayó del lado malo.","uses":[{"file":"data/fiesta.ts","line":134,"ctx":"fg_taba","who":""}]},{"text":"Cayó de costado: no vale. Te devuelvo la plata.","uses":[{"file":"data/fiesta.ts","line":136,"ctx":"fg_taba","who":""}]},{"text":"Desde chico pesco bajo ese muelle. El río tiene humor propio.","uses":[{"file":"data/fraybentos.ts","line":11,"ctx":"Persona (Pescador, aspecto sailor)","who":"Pescador"}]},{"text":"Hoy no vi a la gente de la boletería. Los del barco andan nerviosos y nadie me explica por qué.","uses":[{"file":"data/fraybentos.ts","line":11,"ctx":"Persona (Pescador, aspecto sailor)","who":"Pescador"}]},{"text":"Trabajé treinta años en esa planta. Las cámaras de frío tenían cintas por todos lados: una te llevaba, otra te devolvía.","uses":[{"file":"data/fraybentos.ts","line":13,"ctx":"Persona (Jubilado del Anglo, aspecto obrero)","who":"Jubilado del Anglo"}]},{"text":"Si entrás, no te enojes con las cintas. Cada una va para un solo lado, y se aprende probando.","uses":[{"file":"data/fraybentos.ts","line":13,"ctx":"Persona (Jubilado del Anglo, aspecto obrero)","who":"Jubilado del Anglo"}]},{"text":"Junto latas viejas del Anglo. Dicen que algunas valen plata.","uses":[{"file":"data/fraybentos.ts","line":15,"ctx":"Persona (Nene, aspecto nino)","who":"Nene"}]},{"text":"Una vez encontré una con el dibujo de un barco. ¿Será el mismo de la boletería?","uses":[{"file":"data/fraybentos.ts","line":15,"ctx":"Persona (Nene, aspecto nino)","who":"Nene"}]},{"text":"Traigo carga de Young. Desde que cerraron la salida norte con el zarzal, tengo que dar la vuelta por la ruta.","uses":[{"file":"data/fraybentos.ts","line":17,"ctx":"Persona (Camionero, aspecto camionero)","who":"Camionero"}]},{"text":"Alguien con una herramienta filosa lo arreglaría en un minuto.","uses":[{"file":"data/fraybentos.ts","line":17,"ctx":"Persona (Camionero, aspecto camionero)","who":"Camionero"}]},{"text":"Un camino de tierra sube hacia el norte.","uses":[{"file":"data/maps-act2.ts","line":169,"ctx":"Persona","who":""}]},{"text":"Antes de seguir, hay que resolver lo de la fábrica de Minas: el Equipo PP sigue activo.","uses":[{"file":"data/maps-act2.ts","line":169,"ctx":"Persona","who":""}]},{"text":"Al norte empieza la Ciclovía, un camino pavimentado larguísimo.","uses":[{"file":"data/maps-act2.ts","line":208,"ctx":"Persona","who":""}]},{"text":"Un cartel dice: \"Solo bicicletas\".","uses":[{"file":"data/maps-act2.ts","line":208,"ctx":"Persona","who":""}]},{"text":"El camino al este lleva a Rivera.","uses":[{"file":"data/maps-act2.ts","line":209,"ctx":"Persona","who":""}]},{"text":"Un guardia te frena: \"Sólo pasan entrenadores con la Medalla Tacuarembó\".","uses":[{"file":"data/maps-act2.ts","line":209,"ctx":"Persona","who":""}]},{"text":"El camino al oeste baja hacia Salto.","uses":[{"file":"data/maps-act2.ts","line":210,"ctx":"Persona","who":""}]},{"text":"Un guardia te frena: \"La Ruta 31 está cerrada. Primero resolvé lo de Rivera\".","uses":[{"file":"data/maps-act2.ts","line":210,"ctx":"Persona","who":""}]},{"text":"Un camino sigue hacia el sur, a Paysandú.","uses":[{"file":"data/maps-act2.ts","line":300,"ctx":"Persona","who":""}]},{"text":"Pero la Represa sigue en manos de la gente de gris, y el camino se abre recién cuando tengas la Medalla Salto y haya luz.","uses":[{"file":"data/maps-act2.ts","line":300,"ctx":"Persona","who":""}]},{"text":"El frigorífico es propiedad privada.","uses":[{"file":"data/maps-act2.ts","line":379,"ctx":"Persona (aspecto grunt)","who":""}]},{"text":"La puerta del camarote 2 está cerrada con llave.","uses":[{"file":"data/maps-act2.ts","line":446,"ctx":"Persona","who":""}]},{"text":"La puerta de la bodega tiene un candado grande. Hace falta la llave.","uses":[{"file":"data/maps-act2.ts","line":447,"ctx":"Persona","who":""}]},{"text":"La puerta a la cubierta superior está con llave. Solo la tripulación tiene una.","uses":[{"file":"data/maps-act2.ts","line":463,"ctx":"Persona","who":""}]},{"text":"Boletería del Buquebus \"China Zorrilla\".","uses":[{"file":"data/maps-act2.ts","line":618,"ctx":"Persona (Boletería, aspecto clerk)","who":"Boletería"}]},{"text":"El empleado que despacha los pasajes no vino hoy. Dicen que quedó trabajando en el frigorífico, y no lo dejan salir.","uses":[{"file":"data/maps-act2.ts","line":618,"ctx":"Persona (Boletería, aspecto clerk)","who":"Boletería"}]},{"text":"La Liga de Uruguay: cuatro miembros del Alto Mando y el Campeón.","uses":[{"file":"data/maps-act2.ts","line":804,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"No podés volver atrás una vez que empezás.","uses":[{"file":"data/maps-act2.ts","line":804,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"¡Esperá, {player}!","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"Afuera del pueblo hay criaturas salvajes en los pastizales.","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"No podés irte sin hablar con el Maestro Tabárez. Pasá primero por su laboratorio.","uses":[{"file":"data/maps.ts","line":42,"ctx":"Persona","who":""}]},{"text":"Los turistas vienen desde Buenos Aires en lancha, a ver los astilleros.","uses":[{"file":"data/maps.ts","line":44,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Dicen que en las noches de niebla el río se ve más ancho que el mar.","uses":[{"file":"data/maps.ts","line":44,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Cuando yo era joven, había Ceibos en todas las orillas.","uses":[{"file":"data/maps.ts","line":45,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Ahora casi solo los cuida el Maestro Tabárez.","uses":[{"file":"data/maps.ts","line":45,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"¿Vas al laboratorio? Hoy entregan criaturas.","uses":[{"file":"data/maps.ts","line":46,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Buen compañero te tocó. Cuidalo.","uses":[{"file":"data/maps.ts","line":47,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Si se debilita, pasá por tu casa: tu madre siempre tiene el mate listo.","uses":[{"file":"data/maps.ts","line":47,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Buen día.","uses":[{"file":"data/maps.ts","line":82,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Si tus criaturas están debilitadas, en Montevideo está la Policlínica. Las atienden gratis.","uses":[{"file":"data/maps.ts","line":82,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"El Estadio Centenario está cerrado.","uses":[{"file":"data/maps.ts","line":126,"ctx":"Persona","who":""}]},{"text":"Solo entran quienes tengan las 12 medallas y hayan detenido al Dr. Díaz, el fundador del Equipo PP.","uses":[{"file":"data/maps.ts","line":126,"ctx":"Persona","who":""}]},{"text":"En la Rambla, la gente toma mate y mira el río.","uses":[{"file":"data/maps.ts","line":138,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"El Río de la Plata es marrón por los sedimentos, aunque parezca un mar.","uses":[{"file":"data/maps.ts","line":138,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"El gimnasio de Montevideo es el Palacio de la Luz, la sede de UTE.","uses":[{"file":"data/maps.ts","line":139,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La presidenta, Sofía, usa criaturas de tipo Eléctrico. Las de Tierra no reciben su electricidad.","uses":[{"file":"data/maps.ts","line":139,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La terminal del Buquebus está cerrada por reformas.","uses":[{"file":"data/maps.ts","line":140,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"Los barcos a Buenos Aires salen desde Colonia del Sacramento.","uses":[{"file":"data/maps.ts","line":140,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"El Palacio Salvo fue el edificio más alto de Sudamérica.","uses":[{"file":"data/maps.ts","line":141,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Adentro trabaja gente que sabe mucho de criaturas.","uses":[{"file":"data/maps.ts","line":141,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Esa niebla no es natural. Unos hombres de gris la generan con máquinas.","uses":[{"file":"data/maps.ts","line":177,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Se hacen llamar Equipo PP.","uses":[{"file":"data/maps.ts","line":177,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"La Mano es una escultura de dedos que emergen de la arena.","uses":[{"file":"data/maps.ts","line":211,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Es un recordatorio para los bañistas: la playa Brava es peligrosa.","uses":[{"file":"data/maps.ts","line":211,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Desde el puerto se ve la Isla de Lobos.","uses":[{"file":"data/maps.ts","line":212,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"A veces, en invierno, aparece una ballena cuyo canto se oye desde la costa.","uses":[{"file":"data/maps.ts","line":212,"ctx":"Persona (aspecto sailor)","who":""}]},{"text":"Con este calor, lo que más apetece es un chivito en la playa.","uses":[{"file":"data/maps.ts","line":213,"ctx":"Persona (aspecto swimmer)","who":""}]},{"text":"El gimnasio de acá es la planta potabilizadora de OSE. Su presidenta, Lucía, usa tipo Agua.","uses":[{"file":"data/maps.ts","line":215,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Planta y Eléctrico le hacen daño.","uses":[{"file":"data/maps.ts","line":215,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Un canto profundo sale del agua.","uses":[{"file":"data/maps.ts","line":218,"ctx":"Persona","who":""}]},{"text":"El Equipo PP se llevó la lámpara del faro.","uses":[{"file":"data/maps.ts","line":249,"ctx":"Persona (aspecto keeper)","who":""}]},{"text":"Sin luz, los barcos pueden chocar contra las rocas.","uses":[{"file":"data/maps.ts","line":249,"ctx":"Persona (aspecto keeper)","who":""}]},{"text":"Acá no hay red eléctrica ni calles asfaltadas.","uses":[{"file":"data/maps.ts","line":253,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Los lobos marinos descansan al sol sobre las rocas.","uses":[{"file":"data/maps.ts","line":253,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Las dunas se mueven con el viento. El pueblo entero cambia cada año.","uses":[{"file":"data/maps.ts","line":254,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Cuando sopla el pampero, el cielo queda despejado.","uses":[{"file":"data/maps.ts","line":293,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Dicen que lo trae una criatura enorme con alas de tormenta.","uses":[{"file":"data/maps.ts","line":293,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El camino a la Quebrada de los Cuervos está cerrado.","uses":[{"file":"data/maps.ts","line":329,"ctx":"Persona","who":""}]},{"text":"Hay gente de gris acampando en el valle. No dejan pasar a nadie.","uses":[{"file":"data/maps.ts","line":329,"ctx":"Persona","who":""}]},{"text":"En el fondo de la quebrada hay un arroyo.","uses":[{"file":"data/maps.ts","line":335,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Los cuervos de cabeza roja vuelan en círculos por arriba.","uses":[{"file":"data/maps.ts","line":335,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Treinta y Tres se llama así por los 33 Orientales.","uses":[{"file":"data/maps.ts","line":336,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Acá la historia está en cada rincón.","uses":[{"file":"data/maps.ts","line":336,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Por el fondo de la quebrada corre el arroyo Yerbal.","uses":[{"file":"data/maps.ts","line":390,"ctx":"Persona (aspecto biologo)","who":""}]},{"text":"Los cuervos de cabeza roja hacen nido en los paredones. Este año casi no se ven.","uses":[{"file":"data/maps.ts","line":390,"ctx":"Persona (aspecto biologo)","who":""}]},{"text":"Un pájaro azul enorme, quieto entre dos máquinas.","uses":[{"file":"data/maps.ts","line":398,"ctx":"Persona (aspecto animal:pamperon)","who":""}]},{"text":"La niebla le pesa en las alas. Chispea, pero no puede levantar vuelo.","uses":[{"file":"data/maps.ts","line":398,"ctx":"Persona (aspecto animal:pamperon)","who":""}]},{"text":"Una máquina de niebla del PP. Larga un humo gris hacia el pájaro.","uses":[{"file":"data/maps.ts","line":399,"ctx":"Persona (aspecto machine)","who":""},{"file":"data/maps.ts","line":400,"ctx":"Persona (aspecto machine)","who":""}]},{"text":"La Pluma Azul se pone tibia en tu bolsillo.","uses":[{"file":"data/maps.ts","line":405,"ctx":"Persona","who":""}]},{"text":"Un viento helado baja desde el cielo. El Cardenal Azul volvió a la quebrada.","uses":[{"file":"data/maps.ts","line":405,"ctx":"Persona","who":""}]},{"text":"Rosario es un pueblo de paso, pero bien tranquilo.","uses":[{"file":"data/maps.ts","line":438,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Si te cansás, comprá mate en el almacén.","uses":[{"file":"data/maps.ts","line":438,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Acá se cría ganado de todos los tipos. Cada criatura tiene su lugar en el campo.","uses":[{"file":"data/maps.ts","line":439,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Un ombú solitario se alza en el campo. Su sombra parece moverse sin viento.","uses":[{"file":"data/maps.ts","line":442,"ctx":"Persona","who":""}]},{"text":"El viejo Observatorio del Cerro tiene la puerta clausurada con candados.","uses":[{"file":"data/maps.ts","line":467,"ctx":"Persona","who":""}]},{"text":"Un cartel dice: \"Cerrado por seguridad. Proyecto Pampero\".","uses":[{"file":"data/maps.ts","line":467,"ctx":"Persona","who":""}]},{"text":"Desde la cima del cerro se ve toda la costa.","uses":[{"file":"data/maps.ts","line":475,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El mar acá es más calmo que en Punta del Este.","uses":[{"file":"data/maps.ts","line":475,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Mi abuelo dice que en el mar de Piriápolis se ven toninas en verano.","uses":[{"file":"data/maps.ts","line":476,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"El faro de La Paloma guía a los barcos desde hace casi siglo y medio.","uses":[{"file":"data/maps.ts","line":511,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Más al este, en Cabo Polonio, no hay luz eléctrica.","uses":[{"file":"data/maps.ts","line":512,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Se vive con velas y con lo que da el mar.","uses":[{"file":"data/maps.ts","line":512,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"La puerta de la fábrica está sellada con candados. Hay mucha niebla en las sierras, y alguien adentro. Primero hay que despejar la niebla del este.","uses":[{"file":"data/maps.ts","line":542,"ctx":"Persona","who":""}]},{"text":"Un camino de ceniza baja hacia el oeste. El aire quema: todavía no estás listo para ese calor.","uses":[{"file":"data/maps.ts","line":544,"ctx":"Persona","who":""}]},{"text":"Minas es famosa por el agua de manantial y los cerros.","uses":[{"file":"data/maps.ts","line":549,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Dicen que en las noches de luna llena aparece un felino enorme en las sierras.","uses":[{"file":"data/maps.ts","line":549,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"En la vieja fábrica del este se mueve gente de gris, y de noche se oyen máquinas.","uses":[{"file":"data/maps.ts","line":550,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Un zarzal tapa la entrada. Con un machete se podría pasar.","uses":[{"file":"data/maps.ts","line":550,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Mi abuelo contaba que el yaguareté vivió por acá, antes de que se lo creyera extinto.","uses":[{"file":"data/maps.ts","line":551,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Entre los cerros, unos ojos dorados te observan. Una presencia enorme llena el aire.","uses":[{"file":"data/maps.ts","line":554,"ctx":"Persona","who":""}]},{"text":"Campeón. Volví a casa a entrenar.","uses":[{"file":"data/maps.ts","line":569,"ctx":"Persona (aspecto rival)","who":""}]},{"text":"La próxima vez en el Centenario te gano yo.","uses":[{"file":"data/maps.ts","line":569,"ctx":"Persona (aspecto rival)","who":""}]},{"text":"Soy Gonzalo, ayudante del Maestro Tabárez.","uses":[{"file":"data/maps.ts","line":589,"ctx":"Persona (Gonzalo, aspecto clerk)","who":"Gonzalo"}]},{"text":"Estudiamos cómo las criaturas se adaptan al clima del Río de la Plata.","uses":[{"file":"data/maps.ts","line":589,"ctx":"Persona (Gonzalo, aspecto clerk)","who":"Gonzalo"}]},{"text":"Soy Martín, ayudante del Maestro Tabárez.","uses":[{"file":"data/maps.ts","line":590,"ctx":"Persona (Martín, aspecto biologo)","who":"Martín"}]},{"text":"Medimos el viento del Río de la Plata. El Maestro dice que el pampero tiene un ciclo, como si alguien lo trajera.","uses":[{"file":"data/maps.ts","line":590,"ctx":"Persona (Martín, aspecto biologo)","who":"Martín"}]},{"text":"El candombe nació en los barrios Sur y Palermo.","uses":[{"file":"data/maps.ts","line":597,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Cuando suenan los tambores, hasta las criaturas siguen el ritmo.","uses":[{"file":"data/maps.ts","line":597,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Existe un movimiento llamado Danza Candombe que sube Ataque y Velocidad.","uses":[{"file":"data/maps.ts","line":597,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Los Treinta y Tres Orientales cruzaron el río en 1825.","uses":[{"file":"data/maps.ts","line":603,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Coraje como ese se llama \"garra charrúa\".","uses":[{"file":"data/maps.ts","line":603,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Bienvenido al Palacio Salvo.","uses":[{"file":"data/maps.ts","line":617,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"Si tenés el Mapa de Uruguay, mirá cuántos lugares ya visitaste.","uses":[{"file":"data/maps.ts","line":617,"ctx":"Persona (aspecto clerk)","who":""}]},{"text":"En este palacio guardamos registros de todas las criaturas del país.","uses":[{"file":"data/maps.ts","line":618,"ctx":"Persona (aspecto prof)","who":""}]},{"text":"Algunas evolucionan al subir de nivel. Entrenalas con paciencia.","uses":[{"file":"data/maps.ts","line":618,"ctx":"Persona (aspecto prof)","who":""}]},{"text":"Dato útil: si una criatura está dormida o paralizada, es más fácil capturarla.","uses":[{"file":"data/maps.ts","line":619,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"El tipo Lucha es fuerte contra Normal, Roca y Siniestro.","uses":[{"file":"data/maps.ts","line":620,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Pero sufre contra Volador y Psíquico.","uses":[{"file":"data/maps.ts","line":620,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Siete años sin ganar un Siete. Hoy es mi día.","uses":[{"file":"data/maps.ts","line":706,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Bienvenido al Palacio de la Luz, sede de UTE.","uses":[{"file":"data/maps.ts","line":720,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"La presidenta Sofía usa criaturas de tipo Eléctrico.","uses":[{"file":"data/maps.ts","line":720,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Las de tipo Tierra no reciben daño eléctrico.","uses":[{"file":"data/maps.ts","line":720,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Planta de OSE de Punta del Este.","uses":[{"file":"data/maps.ts","line":730,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Lucía usa tipo Agua. Planta y Eléctrico tienen ventaja.","uses":[{"file":"data/maps.ts","line":730,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Gimnasio de Treinta y Tres.","uses":[{"file":"data/maps.ts","line":740,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"El general Lavalleja usa tipo Roca y Tierra. Agua y Planta son tus mejores aliados.","uses":[{"file":"data/maps.ts","line":740,"ctx":"Persona (aspecto oldman)","who":""}]},{"text":"Primero tenés que vencer a {rival}.","uses":[{"file":"data/maps.ts","line":764,"ctx":"Persona (aspecto cop)","who":""}]},{"text":"El sol de la bandera aparece sobre la Torre de los Homenajes…","uses":[{"file":"data/maps.ts","line":768,"ctx":"Persona","who":""}]},{"text":"La torre del puerto está cerrada con candado.","uses":[{"file":"data/maps.ts","line":981,"ctx":"Persona","who":""}]},{"text":"Hay gente de gris custodiando la puerta y la antena de la cima no para de emitir.","uses":[{"file":"data/maps.ts","line":981,"ctx":"Persona","who":""}]},{"text":"Camino Maldonado: solo pasa quien venció a los tres veteranos del camino.","uses":[{"file":"data/maps.ts","line":1061,"ctx":"Persona (Guardia de la Liga, aspecto cop)","who":"Guardia de la Liga"}]},{"text":"Es la regla de la Liga. Todavía te falta alguno.","uses":[{"file":"data/maps.ts","line":1061,"ctx":"Persona (Guardia de la Liga, aspecto cop)","who":"Guardia de la Liga"}]},{"text":"El gimnasio del Correo está cerrado.","uses":[{"file":"data/maps.ts","line":1132,"ctx":"Persona","who":""}]},{"text":"Un cartel en la puerta dice: \"Volvemos pronto\".","uses":[{"file":"data/maps.ts","line":1132,"ctx":"Persona","who":""}]},{"text":"Soy cartero del Correo y hoy no tengo a quién entregarle nada: la presidenta no está.","uses":[{"file":"data/maps.ts","line":1137,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"Marta salió ayer a llevar un paquete por la cueva de Palmitas, al oeste, y no volvió.","uses":[{"file":"data/maps.ts","line":1137,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"Unos tipos de gris la seguían. Si vas para allá, andá con cuidado.","uses":[{"file":"data/maps.ts","line":1137,"ctx":"Persona (aspecto clerk, evento cartero_marta)","who":""}]},{"text":"¡Marta volvió! Llegó con un paquete de planos y abrió el gimnasio.","uses":[{"file":"data/maps.ts","line":1138,"ctx":"Persona","who":""}]},{"text":"Gracias por ir a buscarla.","uses":[{"file":"data/maps.ts","line":1138,"ctx":"Persona","who":""}]},{"text":"Mi yegua lleva una semana acá y volvió más mansa que nunca.","uses":[{"file":"data/maps.ts","line":1161,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Se nota quién camina mucho: acá se les paga el tiempo en kilómetros.","uses":[{"file":"data/maps.ts","line":1161,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Dejé a mi bicho de compañero y ya cambió de forma. ¡Ni lo reconocí!","uses":[{"file":"data/maps.ts","line":1162,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Si dejás a uno que está por evolucionar, lo hace acá solo.","uses":[{"file":"data/maps.ts","line":1162,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Mi bici tiene dieciocho cambios. Con eso subo cualquier cuesta del norte.","uses":[{"file":"data/maps.ts","line":1183,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Dicen que la Ciclovía tiene tramos tan largos que ni se ve el final.","uses":[{"file":"data/maps.ts","line":1183,"ctx":"Persona (aspecto boy)","who":""}]},{"text":"Vine a arreglar una goma. Siempre se pincha en el peor momento.","uses":[{"file":"data/maps.ts","line":1184,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"A caballo no se pincha, pero tampoco se va al supermercado.","uses":[{"file":"data/maps.ts","line":1184,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"El camino a Lascano está cerrado.","uses":[{"file":"data/maps.ts","line":1298,"ctx":"Persona","who":""}]},{"text":"Desde la Quebrada de los Cuervos bajó una niebla espesa y tapó la ruta. No se ve ni la banquina.","uses":[{"file":"data/maps.ts","line":1298,"ctx":"Persona","who":""}]},{"text":"El Buquebus \"China Zorrilla\" zarpa pronto. Sin ticket no sube nadie.","uses":[{"file":"data/maps.ts","line":1547,"ctx":"Persona (Marinero del muelle, aspecto sailor)","who":"Marinero del muelle"}]},{"text":"Los pasajes los despachan en la empresa. Preguntá por el pueblo.","uses":[{"file":"data/maps.ts","line":1547,"ctx":"Persona (Marinero del muelle, aspecto sailor)","who":"Marinero del muelle"}]},{"text":"La puerta del gimnasio está cerrada.","uses":[{"file":"data/mini-stories.ts","line":81,"ctx":"Persona","who":""}]},{"text":"Un cartel escrito a mano dice: \"Salí a escribir. H. Q.\"","uses":[{"file":"data/mini-stories.ts","line":81,"ctx":"Persona","who":""}]},{"text":"La puerta del gimnasio del INAVI está cerrada.","uses":[{"file":"data/mini-stories.ts","line":186,"ctx":"Persona","who":""}]},{"text":"Una nota pegada en el vidrio dice: \"Estoy en la vendimia. Tomás.\"","uses":[{"file":"data/mini-stories.ts","line":186,"ctx":"Persona","who":""}]},{"text":"Bah, tchê. Acá en Rivera cruzás la calle y ya tá no Brasil.","uses":[{"file":"data/regional-speech.ts","line":19,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Mi vó vendía de un lado y compraba del otro. Tri negocio, barbaridade.","uses":[{"file":"data/regional-speech.ts","line":19,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Bah, acá la gente cruza el puente a Quaraí de chinelo nomás, pra comprar y pasear.","uses":[{"file":"data/regional-speech.ts","line":23,"ctx":"Persona (aspecto artesana)","who":""}]},{"text":"Y las amatistas que salen de las minas son tri lindas. Una barbaridade, tchê.","uses":[{"file":"data/regional-speech.ts","line":23,"ctx":"Persona (aspecto artesana)","who":""}]},{"text":"Bah, mire: en Tacuarembó la Patria Gaucha es cosa seria. Se prende el fogón y pa' qué le cuento.","uses":[{"file":"data/regional-speech.ts","line":27,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Si a usted le gusta el campo, no se pierda el desfile, tchê.","uses":[{"file":"data/regional-speech.ts","line":27,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Bah, tchê. En el campo de Cerro Largo hay más ovejas que gente.","uses":[{"file":"data/regional-speech.ts","line":31,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"Tú cruzas por Río Branco o por Aceguá y sigue todo igual, pero con otro acento. ¿Tú sabías?","uses":[{"file":"data/regional-speech.ts","line":31,"ctx":"Persona (aspecto gaucho)","who":""}]},{"text":"¿Tú sabes por qué la ciudad se llama Treinta y Tres? Por los 33 Orientales, claro.","uses":[{"file":"data/regional-speech.ts","line":35,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Acá la historia está en cada rincón, y el Olimar la canta. Tú quédate un rato y vas a ver.","uses":[{"file":"data/regional-speech.ts","line":35,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Rocha es de playas largas y desiertas, con dunas y lobos marinos. ¿Tú ya las conoces?","uses":[{"file":"data/regional-speech.ts","line":39,"ctx":"Persona (aspecto campesina)","who":""}]},{"text":"En verano viene gente de Argentina y Brasil. En invierno quedamos los de acá, y tú sabes que ahí es otra cosa.","uses":[{"file":"data/regional-speech.ts","line":39,"ctx":"Persona (aspecto campesina)","who":""}]},{"text":"Che, con este calor salteño lo único que da ganas es meterse en las termas. Te arreglan el cuerpo y la cabeza.","uses":[{"file":"data/regional-speech.ts","line":43,"ctx":"Persona (aspecto turista)","who":""}]},{"text":"Y si tenés algo de tipo Siniestro, el líder lo va a sufrir, eh.","uses":[{"file":"data/regional-speech.ts","line":43,"ctx":"Persona (aspecto turista)","who":""}]},{"text":"Bo, acá decimos que la cerveza artesanal más rica del litoral es sanducera. Y no se discute.","uses":[{"file":"data/regional-speech.ts","line":47,"ctx":"Persona (aspecto nino)","who":""}]},{"text":"En verano la playa Park se llena. Todo el mundo baja al río.","uses":[{"file":"data/regional-speech.ts","line":47,"ctx":"Persona (aspecto nino)","who":""}]},{"text":"Buenas. ¿Usted ya vio el Yí? Pasa por el costado de la ciudad, mire qué lindo que es.","uses":[{"file":"data/regional-speech.ts","line":51,"ctx":"Persona (aspecto artesana)","who":""}]},{"text":"Y pa' la fiesta del folklore no queda un lugar libre. La pucha, cómo se llena.","uses":[{"file":"data/regional-speech.ts","line":51,"ctx":"Persona (aspecto artesana)","who":""}]},{"text":"Mire, en Florida se declaró la independencia. Acá la historia anda por la calle, como usted y yo.","uses":[{"file":"data/regional-speech.ts","line":55,"ctx":"Persona (aspecto campesina)","who":""}]},{"text":"La plaza tiene un monumento pa' cada fecha importante. Pase y vea nomás.","uses":[{"file":"data/regional-speech.ts","line":55,"ctx":"Persona (aspecto campesina)","who":""}]},{"text":"¿Qué andás haciendo, botija? Acá el vino es de las quintas de al lado, y se sirve con chivito.","uses":[{"file":"data/regional-speech.ts","line":59,"ctx":"Persona (aspecto turista)","who":""}]},{"text":"Todos los fines de semana alguien prende el fuego con vista a los viñedos.","uses":[{"file":"data/regional-speech.ts","line":59,"ctx":"Persona (aspecto turista)","who":""}]},{"text":"¿Qué hacés, bo? En la Rambla la gente toma mate y mira el río. Re tranqui.","uses":[{"file":"data/regional-speech.ts","line":63,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Parece un mar, pero es marrón por el barro que trae el río. Posta.","uses":[{"file":"data/regional-speech.ts","line":63,"ctx":"Persona (aspecto girl)","who":""}]},{"text":"Todavía quedan entrenadores en el camino.","uses":[{"file":"data/route-stories.ts","line":215,"ctx":"addRouteStory","who":""}]},{"text":"Los animales no se mueven del camino.","uses":[{"file":"data/route-stories.ts","line":246,"ctx":"addRouteStory","who":""}]},{"text":"Un viejo cuida el paso. Si alguien contesta bien su pregunta, los animales se apartan.","uses":[{"file":"data/route-stories.ts","line":260,"ctx":"Persona (Viejo del paso, aspecto oldman, evento route_riddle)","who":"Viejo del paso"}]},{"text":"La tranquera está trabada con tres cerrojos.","uses":[{"file":"data/route-stories.ts","line":377,"ctx":"Persona (Tranquera)","who":"Tranquera"}]},{"text":"Cada lado del camino tiene palancas que los mueven.","uses":[{"file":"data/route-stories.ts","line":377,"ctx":"Persona (Tranquera)","who":"Tranquera"}]},{"text":"Si te equivocás, los cerrojos vuelven a su lugar y se empieza de nuevo.","uses":[{"file":"data/route-stories.ts","line":381,"ctx":"Persona (Peón, aspecto gaucho)","who":"Peón"}]},{"text":"La máquina se apagó. Cuesta aceptarlo, pero no hay vuelta atrás.","uses":[{"file":"data/story.ts","line":291,"ctx":"fogChoice","who":""}]},{"text":"Con el tiempo nos vamos a acostumbrar. Gracias por frenarlos, {player}.","uses":[{"file":"data/story.ts","line":291,"ctx":"fogChoice","who":""}]},{"text":"{player}, por fin te levantaste.","uses":[{"file":"data/story.ts","line":297,"ctx":"mom","who":"Madre"}]},{"text":"El Maestro Tabárez te espera en su laboratorio.","uses":[{"file":"data/story.ts","line":297,"ctx":"mom","who":"Madre"}]},{"text":"Es el edificio de techo violeta. Hoy empieza tu viaje.","uses":[{"file":"data/story.ts","line":297,"ctx":"mom","who":"Madre"}]},{"text":"Sentate y descansá un rato.","uses":[{"file":"data/story.ts","line":300,"ctx":"mom","who":"Madre"}]},{"text":"Te cebo unos mates.","uses":[{"file":"data/story.ts","line":300,"ctx":"mom","who":"Madre"}]},{"text":"Listo. Tus criaturas están recuperadas. Cuidate.","uses":[{"file":"data/story.ts","line":302,"ctx":"mom","who":"Madre"}]},{"text":"Hola, {player}. {rival} ya salió para el laboratorio.","uses":[{"file":"data/story.ts","line":307,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Siempre quiere ser el primero en todo.","uses":[{"file":"data/story.ts","line":307,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Tomá, llevate esto para el viaje.","uses":[{"file":"data/story.ts","line":307,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Mucha suerte en el viaje. Si ves a {rival}, decile que llame a casa.","uses":[{"file":"data/story.ts","line":311,"ctx":"rival_sister","who":"Hermana"}]},{"text":"Llegaste, {player}.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"},{"file":"data/story.ts","line":1256,"ctx":"rival_final","who":"{rival}"}]},{"text":"Soy el Maestro Tabárez. Durante años dirigí a la selección; hoy estudio a las criaturas del Uruguay.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Viven en los montes, las playas, las sierras y hasta en la Rambla.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Hoy vas a elegir a tu primer compañero.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"En la mesa hay tres Pokeballs. Elegí con calma: esa criatura te va a acompañar mucho tiempo.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"{rival} es mi sobrino. Creció entre apuntes y Pokeballs, así que no te la va a hacer fácil.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Hace años estudié el clima del Río de la Plata junto a un colega, Dr. Díaz. Hoy no sé dónde anda, pero el Cardenal Azul sigue siendo un misterio.","uses":[{"file":"data/story.ts","line":319,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"¿Y yo? Llegué primero.","uses":[{"file":"data/story.ts","line":328,"ctx":"prof","who":"{rival}"}]},{"text":"Paciencia, {rival}. Vos elegís después.","uses":[{"file":"data/story.ts","line":329,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Elegí una de las Pokeballs de la mesa.","uses":[{"file":"data/story.ts","line":331,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"¡La carta! Gracias, {player}.","uses":[{"file":"data/story.ts","line":338,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Es de un viejo colega. Dice que el Cardenal Azul se vio por el litoral.","uses":[{"file":"data/story.ts","line":338,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Como prometí: la PokeDex. Registra cada criatura que veas o captures.","uses":[{"file":"data/story.ts","line":339,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Y unas Pokeballs para capturar criaturas salvajes.","uses":[{"file":"data/story.ts","line":339,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Te pedí una carta del almacén de Colonia del Sacramento, siguiendo la Ruta 21.","uses":[{"file":"data/story.ts","line":345,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Cuando la tengas, traémela y te doy la PokeDex.","uses":[{"file":"data/story.ts","line":345,"ctx":"prof","who":"Maestro Tabárez"}]},{"text":"Antes de elegir, tenés que hablar con el Maestro Tabárez.","uses":[{"file":"data/story.ts","line":357,"ctx":"starter","who":""}]},{"text":"Tiene desventaja contra el tuyo, pero no pienso ponértelo fácil.","uses":[{"file":"data/story.ts","line":383,"ctx":"starter","who":"{rival}"}]},{"text":"{player}, probemos a nuestras criaturas.","uses":[{"file":"data/story.ts","line":383,"ctx":"starter","who":"{rival}"}]},{"text":"Combatamos.","uses":[{"file":"data/story.ts","line":383,"ctx":"starter","who":"{rival}"}]},{"text":"Gané. Sigo siendo mejor.","uses":[{"file":"data/story.ts","line":386,"ctx":"starter","who":"{rival}"}]},{"text":"Igual, tu criatura tiene potencial.","uses":[{"file":"data/story.ts","line":386,"ctx":"starter","who":"{rival}"}]},{"text":"Fue suerte.","uses":[{"file":"data/story.ts","line":387,"ctx":"starter","who":"{rival}"}]},{"text":"Voy a entrenar hasta superarte.","uses":[{"file":"data/story.ts","line":387,"ctx":"starter","who":"{rival}"}]},{"text":"Buen combate. Ya atendí a sus criaturas.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Ahora, {player}: el país es grande. Hay doce Gimnasios, y el camino empieza acá, en Carmelo, y termina en Montevideo.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Si conseguís las doce medallas, podés desafiar a la Liga en el Estadio Centenario.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Y tené cuidado con el Equipo PP. Últimamente aparece una niebla extraña en el litoral.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Tu madre puede curar a tus criaturas en casa.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Antes de irte, {player}, te pido un favor. En el almacén de Colonia del Sacramento me guardan una carta.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Seguí por la Ruta 21, entrenando en los pastizales y contra quien te desafíe. No vuelvas hasta tenerla.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Traémela y te entrego la PokeDex y unas Pokeballs. Buen viaje.","uses":[{"file":"data/story.ts","line":390,"ctx":"starter","who":"Maestro Tabárez"}]},{"text":"Que tengas buen viaje. Y tomá mate, que ayuda.","uses":[{"file":"data/story.ts","line":402,"ctx":"gift_te_marcela","who":"Abuelo"}]},{"text":"Un entrenador joven. Tomá, para el camino.","uses":[{"file":"data/story.ts","line":403,"ctx":"gift_te_marcela","who":"Abuelo"}]},{"text":"El Mapa de Uruguay te muestra dónde estás y qué lugares ya visitaste.","uses":[{"file":"data/story.ts","line":409,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Abrilo desde el menú o con la tecla T.","uses":[{"file":"data/story.ts","line":409,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Bienvenido a Colonia del Sacramento. Trabajo en la oficina de turismo del puerto.","uses":[{"file":"data/story.ts","line":410,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Tomá, un mapa del país. Te marca las ciudades y las localidades.","uses":[{"file":"data/story.ts","line":410,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Entre ciudad y ciudad hay localidades sin gimnasio, pero con almacenes y gente con cosas útiles.","uses":[{"file":"data/story.ts","line":413,"ctx":"gift_mapa","who":"Guía de turismo"}]},{"text":"Pesqué en estos arroyos toda la vida.","uses":[{"file":"data/story.ts","line":417,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Somos tres hermanos pescadores: uno pesca en el muelle de Paysandú, otro vive en Minas y el menor tiene casa en Paysandú.","uses":[{"file":"data/story.ts","line":417,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Cada uno te da una caña mejor, pero hay que ganársela con medallas.","uses":[{"file":"data/story.ts","line":417,"ctx":"gift_ros","who":"Pescador retirado"}]},{"text":"Parate frente al agua y apretá A. Con esta caña solo pican las criaturas más comunes. Mi hermano en Minas tiene una mejor.","uses":[{"file":"data/story.ts","line":422,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"¿Qué hacés, guri, todo tranquilo? ¿Te gusta la pesca?","uses":[{"file":"data/story.ts","line":423,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"¿Por qué no te agarrás una de esas cañas viejas que tengo ahí de sobra?","uses":[{"file":"data/story.ts","line":423,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"Parate frente al agua y apretá el botón A. Con esta caña solo pican las criaturas más comunes. Más adelante, mi hermano de Minas te dará una mejor.","uses":[{"file":"data/story.ts","line":426,"ctx":"gift_cana","who":"Pescador del muelle"}]},{"text":"Con la Caña Buena pican criaturas más grandes. La Súper Caña la tiene mi hermano menor, en Paysandú.","uses":[{"file":"data/story.ts","line":430,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"En el muelle de Paysandú hay un pescador que regala una caña para empezar. Pasá primero por ahí.","uses":[{"file":"data/story.ts","line":431,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Veo que ya sabés pescar.","uses":[{"file":"data/story.ts","line":432,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Todavía te falta camino: volvé con tres medallas y te doy una caña buena.","uses":[{"file":"data/story.ts","line":432,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Venís con tres medallas, y eso se nota en el trato con las criaturas.","uses":[{"file":"data/story.ts","line":433,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Tomá: una caña buena, con mejor carnada.","uses":[{"file":"data/story.ts","line":433,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Con ella pican criaturas de más nivel. Mi hermano menor, en Paysandú, guarda la mejor.","uses":[{"file":"data/story.ts","line":436,"ctx":"gift_cana2","who":"Pescador"}]},{"text":"Con la Súper Caña puede picar cualquier cosa. Tené cuidado con lo que sacás.","uses":[{"file":"data/story.ts","line":440,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Mi hermano de Minas tiene la caña buena. Pasá primero por ahí.","uses":[{"file":"data/story.ts","line":441,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"La Súper Caña no es para cualquiera.","uses":[{"file":"data/story.ts","line":442,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Volvé con siete medallas y es tuya.","uses":[{"file":"data/story.ts","line":442,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Siete medallas. Mis hermanos no se equivocaron con vos.","uses":[{"file":"data/story.ts","line":443,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Esta es la mejor caña que armé en mi vida.","uses":[{"file":"data/story.ts","line":443,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Con ella pican todas las criaturas de la zona, incluso las más raras y fuertes.","uses":[{"file":"data/story.ts","line":446,"ctx":"gift_cana3","who":"Pescador"}]},{"text":"Alquilo esta casa todos los veranos. Llevate unos alfajores, que me sobraron.","uses":[{"file":"data/story.ts","line":454,"ctx":"gift_pir","who":"Veraneante"}]},{"text":"Cada verano vienen turistas de todo el continente.","uses":[{"file":"data/story.ts","line":458,"ctx":"gift_pir","who":"Veraneante"}]},{"text":"Me mudé acá por las olas. Tomá, unas Superballs que ya no uso.","uses":[{"file":"data/story.ts","line":463,"ctx":"gift_pal","who":"Surfista"}]},{"text":"Si te gusta el mar, no dejes de probar la pesca en La Paloma.","uses":[{"file":"data/story.ts","line":467,"ctx":"gift_pal","who":"Surfista"}]},{"text":"El viento de Florida no para nunca. Con el hornero ya podés cruzar el país en un rato.","uses":[{"file":"data/story.ts","line":471,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Acá el viento llega de todos lados, y mis horneros aprendieron a usarlo.","uses":[{"file":"data/story.ts","line":472,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Llevate este silbato. Si silbás, un hornero te lleva volando a cualquier ciudad que ya conozcas.","uses":[{"file":"data/story.ts","line":472,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"Se usa desde el menú, en la opción Vuelo. Eso sí: el hornero solo te obedece si ganaste la Medalla Florida.","uses":[{"file":"data/story.ts","line":472,"ctx":"gift_vuelo","who":"Criador de horneros"}]},{"text":"¡Jefa! No contestan ni la torre de Rivera ni la Quebrada.","uses":[{"file":"data/story.ts","line":482,"ctx":"scene_garua","who":"Operario"}]},{"text":"Dicen que anda un entrenador apagándolo todo, de a una.","uses":[{"file":"data/story.ts","line":482,"ctx":"scene_garua","who":"Operario"}]},{"text":"Ya lo sé. Mirá detrás tuyo.","uses":[{"file":"data/story.ts","line":484,"ctx":"scene_garua","who":"Garúa"}]},{"text":"¡Es él!","uses":[{"file":"data/story.ts","line":486,"ctx":"scene_garua","who":"Operario"}]},{"text":"Andá a avisar a la guardia del turno noche. De este me encargo yo.","uses":[{"file":"data/story.ts","line":487,"ctx":"scene_garua","who":"Garúa"}]},{"text":"Mi plan fracasó. Esta vez de verdad.","uses":[{"file":"data/story.ts","line":494,"ctx":"garua","who":"Garúa"}]},{"text":"Así que lograste llegar hasta acá. Otra vez.","uses":[{"file":"data/story.ts","line":495,"ctx":"garua","who":"Garúa"}]},{"text":"Te dije que el plan de la Represa era un ensayo.","uses":[{"file":"data/story.ts","line":495,"ctx":"garua","who":"Garúa"}]},{"text":"Brumario cayó y Bruma también, pero las máquinas siguen en pie. Con ellas, la niebla vuelve en cuestión de semanas.","uses":[{"file":"data/story.ts","line":495,"ctx":"garua","who":"Garúa"}]},{"text":"Desde esta fábrica se va a gobernar el clima del país.","uses":[{"file":"data/story.ts","line":495,"ctx":"garua","who":"Garúa"}]},{"text":"Está bien. Me rindo. Por ahora.","uses":[{"file":"data/story.ts","line":498,"ctx":"garua","who":"Garúa"}]},{"text":"Las máquinas de la fábrica se detienen una por una.","uses":[{"file":"data/story.ts","line":501,"ctx":"garua","who":""}]},{"text":"El humo gris se va con el viento.","uses":[{"file":"data/story.ts","line":501,"ctx":"garua","who":""}]},{"text":"Pero no soy quien manda. PP quiere decir Proyecto Pampero, y el proyecto es del Dr. Díaz.","uses":[{"file":"data/story.ts","line":502,"ctx":"garua","who":"Garúa"}]},{"text":"Dr. Díaz dejó el Anglo hace tiempo. Hoy espera en Montevideo, en el puerto, a quien llegue con las doce medallas.","uses":[{"file":"data/story.ts","line":502,"ctx":"garua","who":"Garúa"}]},{"text":"Llevate esto.","uses":[{"file":"data/story.ts","line":502,"ctx":"garua","who":"Garúa"}]},{"text":"En la oficina de Garúa encontrás una vianda con Restos de Asado, guardada para la guardia nocturna.","uses":[{"file":"data/story.ts","line":504,"ctx":"garua","who":""}]},{"text":"Las máquinas de la fábrica se apagaron. Solo falta Dr. Díaz, en Montevideo.","uses":[{"file":"data/story.ts","line":507,"ctx":"garua","who":""}]},{"text":"El calor se aguanta mejor con un buen mate.","uses":[{"file":"data/story.ts","line":512,"ctx":"gift_dur","who":"Vecino"}]},{"text":"No es fácil vivir con este calor.","uses":[{"file":"data/story.ts","line":513,"ctx":"gift_dur","who":"Vecino"}]},{"text":"Pero la gente de acá se las arregla. Llevate esto, que no lo uso.","uses":[{"file":"data/story.ts","line":513,"ctx":"gift_dur","who":"Vecino"}]},{"text":"Un buen mate se toma despacio y con buena compañía.","uses":[{"file":"data/story.ts","line":520,"ctx":"gift_min","who":"Paisano"}]},{"text":"Los de acá tomamos mate con el agua de las sierras. Probalo, que es de lo mejor.","uses":[{"file":"data/story.ts","line":521,"ctx":"gift_min","who":"Paisano"}]},{"text":"Los carritos de garrapiñada de la Rambla son un clásico.","uses":[{"file":"data/story.ts","line":527,"ctx":"gift_garrapinada","who":"Vecina"}]},{"text":"Compré garrapiñada en la Rambla. Tomá una: hace que tu criatura suba de nivel.","uses":[{"file":"data/story.ts","line":528,"ctx":"gift_garrapinada","who":"Vecina"}]},{"text":"¡{player}! Sabía que ibas a pasar por acá.","uses":[{"file":"data/story.ts","line":537,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Ya tengo la PokeDex llena de apuntes. Vos recién arrancás.","uses":[{"file":"data/story.ts","line":537,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Mi tío dice que en el litoral hay niebla rara. Yo voy a Trinidad por la medalla. Pero antes, una revancha.","uses":[{"file":"data/story.ts","line":537,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Te gané. Así es como se entrena.","uses":[{"file":"data/story.ts","line":543,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Ya curé a tus criaturas: no quiero ganarte con ventaja.","uses":[{"file":"data/story.ts","line":543,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"Nos vemos en Trinidad. Si llegás primero, no le ganes a Elena antes que yo.","uses":[{"file":"data/story.ts","line":544,"ctx":"rival_bosque","who":"{rival}"}]},{"text":"{player}, te estaba esperando.","uses":[{"file":"data/story.ts","line":551,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Me enteré de que le ganaste a Zoraida, en el Anglo.","uses":[{"file":"data/story.ts","line":551,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Yo también estuve entrenando. Veamos quién está más fuerte.","uses":[{"file":"data/story.ts","line":551,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Yo sigo hacia Salto. Nos vemos allá.","uses":[{"file":"data/story.ts","line":554,"ctx":"rival_mvd","who":"{rival}"},{"file":"data/story.ts","line":557,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Esta vez gané yo. Entrená un poco más y volvé a intentarlo cuando quieras.","uses":[{"file":"data/story.ts","line":557,"ctx":"rival_mvd","who":"{rival}"}]},{"text":"Tus criaturas quedaron recuperadas.","uses":[{"file":"data/story.ts","line":558,"ctx":"rival_mvd","who":""},{"file":"data/story.ts","line":738,"ctx":"leader","who":""},{"file":"data/story.ts","line":750,"ctx":"leader","who":""},{"file":"data/story.ts","line":829,"ctx":"rival_ferry","who":""},{"file":"data/story.ts","line":1002,"ctx":"rival_r5","who":""},{"file":"data/story.ts","line":1017,"ctx":"rival_r24","who":""},{"file":"data/story.ts","line":1263,"ctx":"rival_final","who":""}]},{"text":"Bienvenido a la Policlínica.","uses":[{"file":"data/story.ts","line":564,"ctx":"nurse","who":"Enfermera"}]},{"text":"Vamos a atender a tus criaturas.","uses":[{"file":"data/story.ts","line":564,"ctx":"nurse","who":"Enfermera"}]},{"text":"Listo, están recuperadas. Volvé cuando lo necesites.","uses":[{"file":"data/story.ts","line":567,"ctx":"nurse","who":"Enfermera"}]},{"text":"Armé este puesto para los que van a la Liga. Todos llegan con las criaturas cansadas.","uses":[{"file":"data/story.ts","line":571,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"Dejame que las atienda.","uses":[{"file":"data/story.ts","line":571,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"Listo. Que el Camino Maldonado te sea corto.","uses":[{"file":"data/story.ts","line":573,"ctx":"camp_nurse","who":"Enfermera de campaña"}]},{"text":"¿Venís de parte del Maestro Tabárez? Te estaba esperando.","uses":[{"file":"data/story.ts","line":584,"ctx":"shop_carta","who":"Almacenero"}]},{"text":"Tengo esta carta para él. Llevásela con cuidado.","uses":[{"file":"data/story.ts","line":584,"ctx":"shop_carta","who":"Almacenero"}]},{"text":"Si te animás a buscarla, empezá por la cueva de Palmitas: ahí la vieron por última vez.","uses":[{"file":"data/story.ts","line":601,"ctx":"cartero_marta","who":"Cartero"}]},{"text":"Soy Marta, del Correo. Me siguieron hasta acá para quitarme un paquete con planos.","uses":[{"file":"data/story.ts","line":608,"ctx":"marta_cave","who":"Marta"}]},{"text":"Los reclutas del PP me cierran el paso. Si los vencés, te lo agradezco.","uses":[{"file":"data/story.ts","line":608,"ctx":"marta_cave","who":"Marta"}]},{"text":"Gracias, {player}. Sin vos seguiría encerrada entre esas rocas.","uses":[{"file":"data/story.ts","line":609,"ctx":"marta_cave","who":"Marta"}]},{"text":"Llevaban los planos de unas máquinas de niebla. Esto lo tiene que ver todo el país.","uses":[{"file":"data/story.ts","line":609,"ctx":"marta_cave","who":"Marta"}]},{"text":"Ya no hace falta que me trates de usted. Después de esto, somos amigos.","uses":[{"file":"data/story.ts","line":609,"ctx":"marta_cave","who":"Marta"}]},{"text":"Voy ahora mismo para el gimnasio. Cuando llegues, me va a gustar medir tu equipo.","uses":[{"file":"data/story.ts","line":609,"ctx":"marta_cave","who":"Marta"}]},{"text":"Gracias de nuevo. Ojalá todos fueran como vos.","uses":[{"file":"data/story.ts","line":615,"ctx":"route_quest","who":""}]},{"text":"Llevate esto para el camino.","uses":[{"file":"data/story.ts","line":627,"ctx":"route_legend","who":""}]},{"text":"Apagaste la máquina. La niebla de la zona empieza a levantarse. Dentro hay una bolsa con provisiones.","uses":[{"file":"data/story.ts","line":639,"ctx":"route_fog","who":"Máquina de niebla"}]},{"text":"Bienvenido al Casino Peninsula. Las fichas no se cambian por dinero, solo por premios.","uses":[{"file":"data/story.ts","line":645,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Diez fichas salen $500.","uses":[{"file":"data/story.ts","line":645,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Suerte en las máquinas.","uses":[{"file":"data/story.ts","line":647,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"Ya llevás demasiadas fichas. Jugá algunas antes.","uses":[{"file":"data/story.ts","line":649,"ctx":"casino_cashier","who":"Cajero"}]},{"text":"No te alcanza el dinero.","uses":[{"file":"data/story.ts","line":650,"ctx":"casino_cashier","who":"Cajero"},{"file":"game/world.ts","line":1206,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1262,"ctx":"criadero","who":""}]},{"text":"Tragamonedas. Tres iguales pagan; Siete Siete Siete es el premio mayor.","uses":[{"file":"data/story.ts","line":658,"ctx":"casino_slots","who":"Máquina"}]},{"text":"No tenés fichas suficientes.","uses":[{"file":"data/story.ts","line":664,"ctx":"casino_slots","who":"Máquina"}]},{"text":"Mostrador de premios. Se paga solo con fichas.","uses":[{"file":"data/story.ts","line":678,"ctx":"casino_prizes","who":"Premios"}]},{"text":"Volvé cuando tengas más fichas.","uses":[{"file":"data/story.ts","line":681,"ctx":"casino_prizes","who":"Premios"}]},{"text":"No te alcanzan las fichas.","uses":[{"file":"data/story.ts","line":683,"ctx":"casino_prizes","who":"Premios"}]},{"text":"Volvé cuando tus criaturas estén listas. No los dejes salirse con la suya.","uses":[{"file":"data/story.ts","line":707,"ctx":"town_gate","who":""}]},{"text":"Antes de dejar pasar a alguien, quiero ver cómo trata a sus criaturas.","uses":[{"file":"data/story.ts","line":712,"ctx":"town_gate","who":""}]},{"text":"Entrená un poco y volvé. No hay apuro.","uses":[{"file":"data/story.ts","line":715,"ctx":"town_gate","who":""}]},{"text":"¡{player}! ¿Cómo has estado? Siempre es bueno verte por acá.","uses":[{"file":"data/story.ts","line":729,"ctx":"leader","who":""}]},{"text":"Volviste. Estuve entrenando desde la última vez.","uses":[{"file":"data/story.ts","line":732,"ctx":"leader","who":""}]},{"text":"Esta vez no me contengo.","uses":[{"file":"data/story.ts","line":732,"ctx":"leader","who":""}]},{"text":"Buen combate. Volvé cuando hayas recorrido más camino.","uses":[{"file":"data/story.ts","line":739,"ctx":"leader","who":""}]},{"text":"Tomá también esta MT. Enseña un movimiento nuevo a una criatura compatible.","uses":[{"file":"data/story.ts","line":755,"ctx":"leader","who":""}]},{"text":"Y esto es para quien vuela de verdad: el Silbato del Hornero.","uses":[{"file":"data/story.ts","line":757,"ctx":"leader","who":""}]},{"text":"Si silbás, un hornero te lleva volando a cualquier ciudad que ya conozcas. Se usa desde el menú, en Vuelo.","uses":[{"file":"data/story.ts","line":757,"ctx":"leader","who":""}]},{"text":"Y te debía un mate. Lo prometido es deuda.","uses":[{"file":"data/story.ts","line":763,"ctx":"leader","who":""}]},{"text":"Cuando vuelvas a pasar por Tacuarembó, vení a contarme cómo te va.","uses":[{"file":"data/story.ts","line":765,"ctx":"leader","who":""}]},{"text":"¡Eh, vos! ¿Venís por el faro?","uses":[{"file":"data/story.ts","line":773,"ctx":"scene_cabo","who":"Farero"}]},{"text":"Una mujer vestida de gris subió a las rocas con mi lámpara. Desde entonces la luz no gira y los barcos ya no ven la costa.","uses":[{"file":"data/story.ts","line":773,"ctx":"scene_cabo","who":"Farero"}]},{"text":"Si alguien puede hacerla entrar en razón, sos vos. Fijate: ahí viene.","uses":[{"file":"data/story.ts","line":773,"ctx":"scene_cabo","who":"Farero"}]},{"text":"¿Todavía llorando por la lámpara, viejo?","uses":[{"file":"data/story.ts","line":777,"ctx":"scene_cabo","who":"Bruma"}]},{"text":"Sin esa luz nadie ve lo que hacemos en la costa. Y a mí me conviene así.","uses":[{"file":"data/story.ts","line":777,"ctx":"scene_cabo","who":"Bruma"}]},{"text":"Esa lámpara guía a los pescadores desde antes de que vos nacieras. No es tuya.","uses":[{"file":"data/story.ts","line":778,"ctx":"scene_cabo","who":"Farero"}]},{"text":"Ahora es de nadie. Andate a tu faro, que acá hay cosas de adultos.","uses":[{"file":"data/story.ts","line":779,"ctx":"scene_cabo","who":"Bruma"}]},{"text":"Otra vez vos.","uses":[{"file":"data/story.ts","line":787,"ctx":"bruma","who":"Bruma"}]},{"text":"Sin la lámpara del faro, la niebla cubre la costa y nadie ve lo que hacemos.","uses":[{"file":"data/story.ts","line":787,"ctx":"bruma","who":"Bruma"}]},{"text":"Esta vez no hay torre que te frene. Vas a tener que pasar por mí.","uses":[{"file":"data/story.ts","line":787,"ctx":"bruma","who":"Bruma"}]},{"text":"Llevate tu lámpara.","uses":[{"file":"data/story.ts","line":790,"ctx":"bruma","who":"Bruma"}]},{"text":"Igual es tarde: Garúa ya puso a funcionar la fábrica de Minas.","uses":[{"file":"data/story.ts","line":790,"ctx":"bruma","who":"Bruma"}]},{"text":"Y Dr. Díaz nos espera en Montevideo.","uses":[{"file":"data/story.ts","line":790,"ctx":"bruma","who":"Bruma"}]},{"text":"La niebla del cabo empieza a abrirse.","uses":[{"file":"data/story.ts","line":794,"ctx":"bruma","who":""}]},{"text":"Después de tanto tiempo, el mar vuelve a verse.","uses":[{"file":"data/story.ts","line":794,"ctx":"bruma","who":""}]},{"text":"Deberías devolverle la lámpara al farero. Está dentro del faro.","uses":[{"file":"data/story.ts","line":795,"ctx":"bruma","who":""}]},{"text":"La lámpara. La recuperaste.","uses":[{"file":"data/story.ts","line":800,"ctx":"keeper","who":"Farero"}]},{"text":"Esta noche el faro de Cabo Polonio vuelve a funcionar.","uses":[{"file":"data/story.ts","line":800,"ctx":"keeper","who":"Farero"}]},{"text":"Aceptá esto, es lo menos que puedo hacer.","uses":[{"file":"data/story.ts","line":800,"ctx":"keeper","who":"Farero"}]},{"text":"Y llevate también este farol de gaucho. Alumbra hasta el túnel más oscuro.","uses":[{"file":"data/story.ts","line":803,"ctx":"keeper","who":"Farero"}]},{"text":"Las sierras entre Piriápolis y Minas son pura oscuridad: lo vas a necesitar.","uses":[{"file":"data/story.ts","line":803,"ctx":"keeper","who":"Farero"}]},{"text":"Se usa desde el menú, en Destello. Eso sí: solo te va a obedecer si ganaste la Medalla Maldonado.","uses":[{"file":"data/story.ts","line":803,"ctx":"keeper","who":"Farero"}]},{"text":"Gracias a vos, los barcos navegan seguros.","uses":[{"file":"data/story.ts","line":808,"ctx":"keeper","who":"Farero"}]},{"text":"Se llevaron la lámpara. Fue una mujer vestida de gris, con capa.","uses":[{"file":"data/story.ts","line":809,"ctx":"keeper","who":"Farero"}]},{"text":"Sigue afuera, del lado de las rocas.","uses":[{"file":"data/story.ts","line":809,"ctx":"keeper","who":"Farero"}]},{"text":"Las máquinas que había en las cámaras de frío no eran de la fábrica. Las trajo alguien de afuera.","uses":[{"file":"data/story.ts","line":815,"ctx":"frb_historia","who":""}]},{"text":"Y esa niebla artificial que se vende por el litoral, creo que no es una casualidad.","uses":[{"file":"data/story.ts","line":815,"ctx":"frb_historia","who":""}]},{"text":"Esta ciudad fue la cocina del mundo. Que no sea ahora un depósito de máquinas ajenas.","uses":[{"file":"data/story.ts","line":815,"ctx":"frb_historia","who":""}]},{"text":"Veo que pasaste por el museo. Zoraida cuida ese lugar como a un tesoro.","uses":[{"file":"data/story.ts","line":816,"ctx":"frb_historia","who":""}]},{"text":"Las cajas del museo se usaban para despachar mercadería entre depósitos. Ahora las usa ella para recibir a los visitantes.","uses":[{"file":"data/story.ts","line":816,"ctx":"frb_historia","who":""}]},{"text":"Si te interesa la historia del Anglo, andá a ver el frigorífico viejo. Pero con cuidado: se movió gente rara por ahí.","uses":[{"file":"data/story.ts","line":816,"ctx":"frb_historia","who":""}]},{"text":"Soy docente de historia. Fray Bentos nació alrededor de una fábrica de extracto de carne, hace más de un siglo y medio.","uses":[{"file":"data/story.ts","line":817,"ctx":"frb_historia","who":""}]},{"text":"El Anglo faenaba miles de reses por día y mandaba conservas a medio mundo. Por eso le decían \"la cocina del mundo\".","uses":[{"file":"data/story.ts","line":817,"ctx":"frb_historia","who":""}]},{"text":"Hoy el museo guarda esa historia. Preguntá por Zoraida, la directora.","uses":[{"file":"data/story.ts","line":817,"ctx":"frb_historia","who":""}]},{"text":"{player}. Sabía que ibas a subir a este barco.","uses":[{"file":"data/story.ts","line":822,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Alguien me escribió diciendo que trabaja con mi tío en un estudio del clima. Me pidió ayuda y le pasé un par de datos del laboratorio.","uses":[{"file":"data/story.ts","line":822,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Si es ciencia, quiero ser parte. Pero antes de que entres al camarote del capitán, veamos quién es más fuerte.","uses":[{"file":"data/story.ts","line":822,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Bien. Pasá vos primero, el capitán te espera.","uses":[{"file":"data/story.ts","line":825,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Pero en el Centenario te gano.","uses":[{"file":"data/story.ts","line":825,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Todavía te falta. No pasa nada: entrená y volvé a medirte conmigo en el Centenario.","uses":[{"file":"data/story.ts","line":828,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Dejo el paso libre al camarote del capitán.","uses":[{"file":"data/story.ts","line":828,"ctx":"rival_ferry","who":"{rival}"}]},{"text":"Cuando la ballena canta, hasta el motor del barco parece callarse.","uses":[{"file":"data/story.ts","line":835,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"Soy biólogo marino. Viajo para estudiar a la criatura que canta frente a Punta del Este.","uses":[{"file":"data/story.ts","line":836,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"Mirá estas fotos: una ballena enorme, de color plata, que solo aparece en invierno.","uses":[{"file":"data/story.ts","line":836,"ctx":"ferry_bio","who":"Biólogo"}]},{"text":"¡Los datos de Ballenaplata se agregaron a la PokeDex!","uses":[{"file":"data/story.ts","line":840,"ctx":"ferry_bio","who":""}]},{"text":"Además, entre las cosas del capataz había un objeto que sirve para equipar a una criatura.","uses":[{"file":"data/story.ts","line":857,"ctx":"event_boss","who":""}]},{"text":"PEAJE","uses":[{"file":"data/story.ts","line":865,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Gracias. Buen viaje y cuidado con las criaturas en la ruta.","uses":[{"file":"data/story.ts","line":868,"ctx":"toll_booth","who":"Peaje"}]},{"text":"¿Otra vez sin plata? Bueno, ya van varias veces.","uses":[{"file":"data/story.ts","line":873,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Está bien, por esta vez pasás. Pero lo vas a pagar con la patente, como todo en este país.","uses":[{"file":"data/story.ts","line":873,"ctx":"toll_booth","who":"Peaje"}]},{"text":"No te alcanza para el peaje. Volvé cuando tengas $115.","uses":[{"file":"data/story.ts","line":877,"ctx":"toll_booth","who":"Peaje"}]},{"text":"Gracias otra vez, {player}. Sin vos esto seguiría tomado.","uses":[{"file":"data/story.ts","line":883,"ctx":"event_owner","who":"Dueño"}]},{"text":"Pasá cuando quieras.","uses":[{"file":"data/story.ts","line":883,"ctx":"event_owner","who":"Dueño"}]},{"text":"Mi hermano ya no está mareado. Gracias por el favor.","uses":[{"file":"data/story.ts","line":888,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"El Buquebus \"China Zorrilla\" está en la terminal, al lado del muelle.","uses":[{"file":"data/story.ts","line":889,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Mi hermano, el capitán, está en su camarote. Llevale un Mate: en el almacén venden.","uses":[{"file":"data/story.ts","line":889,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Soy el farero de Fray Bentos. Hace cuarenta años que miro el río desde acá arriba.","uses":[{"file":"data/story.ts","line":890,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Mi hermano es el capitán del Buquebus \"China Zorrilla\", el ferry nuevo que lleva el nombre de la actriz. Está atracado en la terminal.","uses":[{"file":"data/story.ts","line":890,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Desde la prueba de mar anda mareado, y no hay nada que lo calme como un Mate bien cebado.","uses":[{"file":"data/story.ts","line":890,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Para subir hace falta un ticket, y los reparte alguien de la empresa. Yo solo sé que hay gente de la planta que trabaja en el frigorífico a la fuerza.","uses":[{"file":"data/story.ts","line":890,"ctx":"keeper_colonia","who":"Farero"}]},{"text":"Gracias por la credencial. Cuando salgas de este laberinto, subí al barco con el ticket.","uses":[{"file":"data/story.ts","line":895,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"¡Esa es mi credencial! Pero con la jefa de la banda acá adentro no puedo despachar ningún pasaje.","uses":[{"file":"data/story.ts","line":897,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si ella se va, el ticket es tuyo. Quedate con la credencial hasta entonces.","uses":[{"file":"data/story.ts","line":897,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"¡Esa es mi credencial! Estaba perdida en alguna de las cintas.","uses":[{"file":"data/story.ts","line":900,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"No soy del PP. Me tienen acá adentro manejando las cintas porque soy el único que las conoce.","uses":[{"file":"data/story.ts","line":902,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Soy de los que despachan los pasajes del Buquebus. Tomá uno, es lo mínimo.","uses":[{"file":"data/story.ts","line":902,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si el capitán anda mareado, llevale un Mate. Dicen que es lo único que lo calma.","uses":[{"file":"data/story.ts","line":905,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Yo trabajo en el Anglo desde antes de que llegaran estos del PP. Me tienen encerrado en esta oficina, a la vista de la jefa.","uses":[{"file":"data/story.ts","line":907,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Perdí mi credencial de operario en algún rincón de las cintas y sin ella no puedo ni salir a cobrar.","uses":[{"file":"data/story.ts","line":907,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Si la encontrás, hablamos. Yo despacho los pasajes del Buquebus.","uses":[{"file":"data/story.ts","line":907,"ctx":"obrero_anglo","who":"Operario"}]},{"text":"Uf… perdón. Soy el capitán de este barco, y estoy mareado desde que zarpamos de prueba.","uses":[{"file":"data/story.ts","line":912,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Lo único que me calma es un Mate, de esos bien cebados. Pero acá a bordo se acabó la yerba.","uses":[{"file":"data/story.ts","line":912,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Si me traés un Mate, te lo voy a agradecer toda la vida.","uses":[{"file":"data/story.ts","line":913,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"En el almacén de Fray Bentos venden.","uses":[{"file":"data/story.ts","line":913,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"El capitán suspira. Cuando quieras, acá estoy.","uses":[{"file":"data/story.ts","line":914,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"{player} le dio el Mate al capitán. Poco a poco recupera el color.","uses":[{"file":"data/story.ts","line":917,"ctx":"ferry_captain","who":""}]},{"text":"Mucho mejor. Me salvaste, {player}.","uses":[{"file":"data/story.ts","line":918,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"En agradecimiento, tomá este machete: lo uso para abrir paso entre los zarzales del muelle viejo.","uses":[{"file":"data/story.ts","line":918,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Se usa parándote frente al zarzal y apretando A. En Fray Bentos la guardia solo deja cortar a quien ganó la Medalla de este pueblo; en los caminos más al norte, a quien ganó la Medalla Salto.","uses":[{"file":"data/story.ts","line":918,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"También te dejo unas Pokeballs y unos panes que el barco no va a usar.","uses":[{"file":"data/story.ts","line":921,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Ahora, a trabajar: el barco zarpa en minutos rumbo a Buenos Aires.","uses":[{"file":"data/story.ts","line":927,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"Todos los pasajeros tienen que bajar. ¡Gracias por todo!","uses":[{"file":"data/story.ts","line":927,"ctx":"ferry_captain","who":"Capitán"}]},{"text":"El Buquebus \"China Zorrilla\" ya no se ve en el río. No va a volver a este puerto.","uses":[{"file":"data/story.ts","line":929,"ctx":"ferry_captain","who":""}]},{"text":"Con el Machete vas a poder abrir los zarzales de la salida norte de Fray Bentos cuando ganes la Medalla del gimnasio del pueblo.","uses":[{"file":"data/story.ts","line":930,"ctx":"ferry_captain","who":""}]},{"text":"Una figura pálida sostiene un farol apagado.","uses":[{"file":"data/story.ts","line":935,"ctx":"anima","who":"Ánima"}]},{"text":"Soy el Sereno de la torre. Alguien me sacó el farol y escondió acá una pieza que apaga todo.","uses":[{"file":"data/story.ts","line":935,"ctx":"anima","who":"Ánima"}]},{"text":"No me dejan descansar. Si querés llevarte la pieza, antes tenés que vencerme.","uses":[{"file":"data/story.ts","line":935,"ctx":"anima","who":"Ánima"}]},{"text":"El farol se prende solo. La pieza de la máquina queda en el suelo, apagada.","uses":[{"file":"data/story.ts","line":940,"ctx":"anima","who":"Ánima"}]},{"text":"Gracias. Ahora puedo descansar.","uses":[{"file":"data/story.ts","line":940,"ctx":"anima","who":"Ánima"}]},{"text":"Llevate esto: lo usaban los serenos para ver en la oscuridad.","uses":[{"file":"data/story.ts","line":940,"ctx":"anima","who":"Ánima"}]},{"text":"Desde la ventana de la torre, las Luces Malas de Cerro Largo se apagan una por una.","uses":[{"file":"data/story.ts","line":944,"ctx":"anima","who":""}]},{"text":"Se oyen pasos apurados por el sendero.","uses":[{"file":"data/story.ts","line":950,"ctx":"scene_qb_ayudante","who":""}]},{"text":"¡{player}! Soy Martín, el ayudante del Maestro Tabárez. Nos vimos en el laboratorio de Carmelo.","uses":[{"file":"data/story.ts","line":952,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"El Maestro me mandó a medir el viento de la quebrada. Hace tres días que el aire está quieto, y eso acá no pasa nunca.","uses":[{"file":"data/story.ts","line":952,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"Cada tantos años el Cardenal Azul baja a esta quebrada a descansar, después de cruzar el país detrás del pampero.","uses":[{"file":"data/story.ts","line":953,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"El PP lo sabía. Rodearon el nido con máquinas: si la niebla no lo deja levantar vuelo, el viento no vuelve a soplar.","uses":[{"file":"data/story.ts","line":953,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"Tus criaturas están cansadas. Dejame darles una mano.","uses":[{"file":"data/story.ts","line":954,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"Yo voy a avisarle al Maestro. Viene en camino desde Carmelo.","uses":[{"file":"data/story.ts","line":956,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"Arriba no te puedo ayudar: con los reclutas del PP no tengo chance.","uses":[{"file":"data/story.ts","line":956,"ctx":"scene_qb_ayudante","who":"Martín"}]},{"text":"Así que vos sos el entrenador que molesta a mis reclutas.","uses":[{"file":"data/story.ts","line":962,"ctx":"brumario","who":"Brumario"}]},{"text":"Soy Brumario, jefe del Equipo PP en el este.","uses":[{"file":"data/story.ts","line":962,"ctx":"brumario","who":"Brumario"}]},{"text":"Mirá atrás mío. El Cardenal Azul limpia el cielo y disipa la niebla. Mientras esté acá, el pampero no sopla.","uses":[{"file":"data/story.ts","line":962,"ctx":"brumario","who":"Brumario"}]},{"text":"Si lo capturo, el país será nuestro: gris, quieto, sin viento.","uses":[{"file":"data/story.ts","line":962,"ctx":"brumario","who":"Brumario"}]},{"text":"Apartate de mi camino.","uses":[{"file":"data/story.ts","line":962,"ctx":"brumario","who":"Brumario"}]},{"text":"Perdí. Pero esto no se termina acá.","uses":[{"file":"data/story.ts","line":965,"ctx":"brumario","who":"Brumario"}]},{"text":"Yo sólo respondo al Dr. Díaz. Él nunca se ensucia las manos.","uses":[{"file":"data/story.ts","line":965,"ctx":"brumario","who":"Brumario"}]},{"text":"Si querés seguir, la fábrica de Minas es el próximo paso. Garúa la dirige.","uses":[{"file":"data/story.ts","line":965,"ctx":"brumario","who":"Brumario"}]},{"text":"Una de las máquinas tose y se apaga.","uses":[{"file":"data/story.ts","line":970,"ctx":"brumario","who":""}]},{"text":"La otra se queda sin humo.","uses":[{"file":"data/story.ts","line":973,"ctx":"brumario","who":""}]},{"text":"El Cardenal Azul abre las alas. Te mira un momento, como si te conociera.","uses":[{"file":"data/story.ts","line":973,"ctx":"brumario","who":""}]},{"text":"Un viento helado baja de las sierras.","uses":[{"file":"data/story.ts","line":978,"ctx":"brumario","who":""}]},{"text":"El Cardenal Azul se aleja hacia el sur, y la niebla de la Quebrada se disipa.","uses":[{"file":"data/story.ts","line":978,"ctx":"brumario","who":""}]},{"text":"Donde estaba el pájaro quedó una pluma azul que chispea.","uses":[{"file":"data/story.ts","line":979,"ctx":"brumario","who":""}]},{"text":"Llegué tarde para verlo de cerca, pero lo vi irse. Hacía veinte años que no lo veía volar.","uses":[{"file":"data/story.ts","line":982,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Martín me contó lo que hiciste en la subida. Gracias, {player}.","uses":[{"file":"data/story.ts","line":982,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Te debo la historia completa.","uses":[{"file":"data/story.ts","line":983,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"El pampero no es solo un viento. Lo trae el Cardenal Azul: cuando cruza el país, el cielo se limpia y la niebla se va.","uses":[{"file":"data/story.ts","line":983,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Con Díaz lo estudiamos años. Lo llamamos Proyecto Pampero: queríamos predecir el clima siguiendo su ciclo.","uses":[{"file":"data/story.ts","line":983,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Díaz quiso venderlo. Si el Cardenal deja de volar, la niebla se queda, y la niebla se puede cobrar.","uses":[{"file":"data/story.ts","line":984,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Me negué y se fue. Ahora sé hasta dónde estaba dispuesto a llegar.","uses":[{"file":"data/story.ts","line":984,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"En Fray Bentos te dije que tu compañero guarda un eco del ciclo del viento. Es el eco del Cardenal: nació en mi laboratorio el día que pasó volando sobre Carmelo.","uses":[{"file":"data/story.ts","line":984,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Esa pluma la dejó para vos. Guardala.","uses":[{"file":"data/story.ts","line":985,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Cuando el PP ya no exista, el Cardenal va a volver a descansar acá. Si la llevás, te va a reconocer.","uses":[{"file":"data/story.ts","line":985,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Nuestro laboratorio era el viejo Observatorio del Cerro, en Piriápolis. Si pasás por ahí, fijate qué quedó.","uses":[{"file":"data/story.ts","line":988,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"Y seguí hacia la costa: en el faro de Cabo Polonio falta una lámpara, y en Minas hay una fábrica abandonada que volvió a funcionar.","uses":[{"file":"data/story.ts","line":988,"ctx":"brumario","who":"Maestro Tabárez"}]},{"text":"{player}. Te estaba esperando en el camino.","uses":[{"file":"data/story.ts","line":995,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Pasé por la Quebrada de los Cuervos. Estaba vacía: ni un cuervo, ni un nido.","uses":[{"file":"data/story.ts","line":995,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Los datos que mandé al PP sirvieron para esto. Me usaron, y yo les creí.","uses":[{"file":"data/story.ts","line":995,"ctx":"rival_r5","who":"{rival}"}]},{"text":"No te pido perdón. Te pido un combate: necesito saber si todavía sirvo para algo.","uses":[{"file":"data/story.ts","line":995,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Bien jugado. Yo voy a hablar con mi tío.","uses":[{"file":"data/story.ts","line":998,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Nos vemos en el Centenario.","uses":[{"file":"data/story.ts","line":998,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Todavía te falta un poco. Entrená y seguí.","uses":[{"file":"data/story.ts","line":1001,"ctx":"rival_r5","who":"{rival}"}]},{"text":"Yo voy a hablar con mi tío.","uses":[{"file":"data/story.ts","line":1001,"ctx":"rival_r5","who":"{rival}"}]},{"text":"{player}. Hablé con mi tío. Fue socio del Dr. Díaz y nunca me lo dijo.","uses":[{"file":"data/story.ts","line":1010,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Ya no trabajo para nadie del PP: me di cuenta tarde de a quién le estaba creyendo.","uses":[{"file":"data/story.ts","line":1010,"ctx":"rival_r24","who":"{rival}"}]},{"text":"No te pido ayuda, te pido que me veas pelear bien una vez. Falta Durazno y después la capital, y no pienso llegar segundo.","uses":[{"file":"data/story.ts","line":1010,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Andá vos. Yo te sigo de cerca.","uses":[{"file":"data/story.ts","line":1013,"ctx":"rival_r24","who":"{rival}"}]},{"text":"En el Centenario nos vemos las caras.","uses":[{"file":"data/story.ts","line":1013,"ctx":"rival_r24","who":"{rival}"},{"file":"data/story.ts","line":1016,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Esta vez gané yo, pero la capital es cosa tuya. Andá.","uses":[{"file":"data/story.ts","line":1016,"ctx":"rival_r24","who":"{rival}"}]},{"text":"Bienvenido a Mi Zoo. Es un parque con criaturas de todo el país, sueltas y a la vista.","uses":[{"file":"data/story.ts","line":1023,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Se paga por tiempo de visita. Pasado ese tiempo suena una campana y los guardias te acompañan a la salida.","uses":[{"file":"data/story.ts","line":1023,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Un minuto antes te vamos a avisar. No se devuelve el dinero si salís antes.","uses":[{"file":"data/story.ts","line":1023,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Cuando quieras, acá estamos.","uses":[{"file":"data/story.ts","line":1026,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"No te alcanza el dinero para esa entrada.","uses":[{"file":"data/story.ts","line":1028,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Te damos 30 Safari Balls y 15 Galletas de Campaña. Con la galleta, la criatura se encariña y es más fácil de atrapar. Todo se devuelve al salir.","uses":[{"file":"data/story.ts","line":1031,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Que disfrutes la visita.","uses":[{"file":"data/story.ts","line":1031,"ctx":"safari_clerk","who":"Boletería"}]},{"text":"Gracias por la visita. Te acompaño a la salida.","uses":[{"file":"data/story.ts","line":1040,"ctx":"safari_exit","who":"Guardia"}]},{"text":"¡{player}! Por fin te encuentro. Soy Gonzalo, el ayudante del Maestro Tabárez. Nos vimos en el laboratorio.","uses":[{"file":"data/story.ts","line":1049,"ctx":"huevo_ayudante","who":""}]},{"text":"Felicitaciones por la medalla. El Maestro va a estar contento.","uses":[{"file":"data/story.ts","line":1049,"ctx":"huevo_ayudante","who":""}]},{"text":"Te traigo un encargo. Un estanciero de Palmitas encontró un huevo entre los pajonales y se lo mandó al Maestro.","uses":[{"file":"data/story.ts","line":1050,"ctx":"huevo_ayudante","who":""}]},{"text":"Nadie supo decirnos de qué criatura es. El Maestro cree que los huevos nacen antes si viajan con criaturas fuertes, y quiere que lo lleves vos.","uses":[{"file":"data/story.ts","line":1050,"ctx":"huevo_ayudante","who":""}]},{"text":"Cuidalo. Va a nacer cuando haya caminado un buen trecho con vos.","uses":[{"file":"data/story.ts","line":1052,"ctx":"huevo_ayudante","who":""}]},{"text":"Cuando nazca, avisale al Maestro qué salió. Yo vuelvo a Carmelo.","uses":[{"file":"data/story.ts","line":1052,"ctx":"huevo_ayudante","who":""}]},{"text":"No esperaba visitas. Soy Almada, fui alumno del Maestro Tabárez en este mismo observatorio.","uses":[{"file":"data/story.ts","line":1066,"ctx":"almada","who":"Almada"}]},{"text":"Estudiábamos cómo el Pampero ordena el clima del Río de la Plata. Dr. Díaz y Tabárez dirigían el proyecto.","uses":[{"file":"data/story.ts","line":1066,"ctx":"almada","who":"Almada"}]},{"text":"Cuando Tabárez se negó a vender los datos, Dr. Díaz se quedó con los instrumentos y yo me fui con él.","uses":[{"file":"data/story.ts","line":1066,"ctx":"almada","who":"Almada"}]},{"text":"Pensé que íbamos a proteger el clima. Resulta que quería controlarlo.","uses":[{"file":"data/story.ts","line":1066,"ctx":"almada","who":"Almada"}]},{"text":"Acá guardo el registro original. Si querés leerlo, ganame primero.","uses":[{"file":"data/story.ts","line":1067,"ctx":"almada","who":"Almada"}]},{"text":"Desde el observatorio, el cielo se ve limpio.","uses":[{"file":"data/story.ts","line":1073,"ctx":"almada","who":""}]},{"text":"Tomá el registro. Está firmado por los dos: Tabárez y Dr. Díaz.","uses":[{"file":"data/story.ts","line":1074,"ctx":"almada","who":"Almada"}]},{"text":"La última página la escribió Dr. Díaz: \"El Cardenal Azul tiene un ciclo. Si lo interrumpo, la niebla es mía para siempre\".","uses":[{"file":"data/story.ts","line":1074,"ctx":"almada","who":"Almada"}]},{"text":"Por eso quiere capturarlo. No lo odia: lo necesita.","uses":[{"file":"data/story.ts","line":1074,"ctx":"almada","who":"Almada"}]},{"text":"Dejo el Equipo PP. Voy a llevarle esto a Tabárez en persona.","uses":[{"file":"data/story.ts","line":1075,"ctx":"almada","who":"Almada"}]},{"text":"Y esta MT era del observatorio: se usaba para medir los temblores del cerro.","uses":[{"file":"data/story.ts","line":1075,"ctx":"almada","who":"Almada"}]},{"text":"Tu celular vibra. Es Facu:","uses":[{"file":"data/story.ts","line":1078,"ctx":"almada","who":""}]},{"text":"\"Mi tío me contó que Almada fue su mejor alumno. Si lo convenciste de volver, ya hiciste más que yo.","uses":[{"file":"data/story.ts","line":1078,"ctx":"almada","who":""}]},{"text":"No pienso quedarme atrás. Nos vemos en el camino.\"","uses":[{"file":"data/story.ts","line":1078,"ctx":"almada","who":""}]},{"text":"Volvimos a vernos.","uses":[{"file":"data/story.ts","line":1082,"ctx":"bruma2","who":"Bruma"}]},{"text":"Después del Anglo juré que no me ganarías otra vez.","uses":[{"file":"data/story.ts","line":1082,"ctx":"bruma2","who":"Bruma"}]},{"text":"Esta torre emite la niebla que cubre Rivera. Mientras esté encendida, nadie ve lo que hacemos.","uses":[{"file":"data/story.ts","line":1082,"ctx":"bruma2","who":"Bruma"}]},{"text":"La baliza del transmisor parpadea… y se apaga.","uses":[{"file":"data/story.ts","line":1088,"ctx":"bruma2","who":""}]},{"text":"La niebla de Rivera sube y desaparece.","uses":[{"file":"data/story.ts","line":1088,"ctx":"bruma2","who":""}]},{"text":"Perdí… otra vez.","uses":[{"file":"data/story.ts","line":1089,"ctx":"bruma2","who":"Bruma"}]},{"text":"Dr. Díaz no se va a quedar en el norte. Dicen que prepara algo grande en Montevideo.","uses":[{"file":"data/story.ts","line":1089,"ctx":"bruma2","who":"Bruma"}]},{"text":"Hacé lo que quieras. Brumario espera en la Quebrada de los Cuervos.","uses":[{"file":"data/story.ts","line":1089,"ctx":"bruma2","who":"Bruma"}]},{"text":"Así que vos sos el entrenador que nos molesta.","uses":[{"file":"data/story.ts","line":1095,"ctx":"garua2","who":"Garúa"}]},{"text":"Soy Garúa, comandante del Equipo PP.","uses":[{"file":"data/story.ts","line":1095,"ctx":"garua2","who":"Garúa"}]},{"text":"La Represa mueve las torres: sin electricidad no hay niebla. Y yo controlo los interruptores.","uses":[{"file":"data/story.ts","line":1095,"ctx":"garua2","who":"Garúa"}]},{"text":"Las compuertas de la represa se abren.","uses":[{"file":"data/story.ts","line":1101,"ctx":"garua2","who":""}]},{"text":"En la ciudad, las luces se prenden una por una.","uses":[{"file":"data/story.ts","line":1101,"ctx":"garua2","who":""}]},{"text":"Perdí. Pero esto es solo una pieza: Dr. Díaz tiene otra torre en Rivera, y mucho más que eso.","uses":[{"file":"data/story.ts","line":1102,"ctx":"garua2","who":"Garúa"}]},{"text":"Yo vuelvo a mi fábrica de Minas. Si querés alcanzarme, tendrás que llegar hasta allá.","uses":[{"file":"data/story.ts","line":1102,"ctx":"garua2","who":"Garúa"}]},{"text":"Así que sos vos el que anda haciendo ruido en Fray Bentos.","uses":[{"file":"data/story.ts","line":1109,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Soy Bruma, administradora del Equipo PP.","uses":[{"file":"data/story.ts","line":1109,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Este frigorífico guarda las máquinas de niebla. Dr. Díaz las necesita funcionando.","uses":[{"file":"data/story.ts","line":1109,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Y vos tenés algo que él lleva años buscando: esa criatura que te acompaña guarda el eco del Cardenal Azul. Entregámela y nadie se lastima.","uses":[{"file":"data/story.ts","line":1109,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Perdí. Pero el proyecto es más grande que este frigorífico.","uses":[{"file":"data/story.ts","line":1112,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Dr. Díaz tiene torres y una represa, y yo no soy la única que sigue sus órdenes.","uses":[{"file":"data/story.ts","line":1112,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"Entre las cosas de Bruma queda un objeto raro: un Repartir Exp, de los que el PP usaba para entrenar a su gente.","uses":[{"file":"data/story.ts","line":1114,"ctx":"bruma_anglo","who":""}]},{"text":"Bruma. Sé para quién trabajás.","uses":[{"file":"data/story.ts","line":1118,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Decile a Dr. Díaz que esta vez voy a ir yo mismo.","uses":[{"file":"data/story.ts","line":1118,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Maestro… Él dijo que usted no vendría.","uses":[{"file":"data/story.ts","line":1119,"ctx":"bruma_anglo","who":"Bruma"}]},{"text":"{player}, tengo que decirte algo que callé demasiado tiempo.","uses":[{"file":"data/story.ts","line":1123,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Tu compañero nació en mi laboratorio durante el Proyecto Pampero. Guarda un eco del ciclo del viento, y por eso el PP te sigue.","uses":[{"file":"data/story.ts","line":1123,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Perdoname por no habértelo dicho en Carmelo. Cuidalo mucho.","uses":[{"file":"data/story.ts","line":1123,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Una cosa más. Traje esto del laboratorio: un Medidor de Niebla.","uses":[{"file":"data/story.ts","line":1124,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Mide cuánta niebla del Equipo PP hay en el aire de todo el país. Hoy marca casi el máximo.","uses":[{"file":"data/story.ts","line":1124,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Cada planta del PP que cierres lo va a hacer bajar. Quiero verlo en cero.","uses":[{"file":"data/story.ts","line":1124,"ctx":"bruma_anglo","who":"Maestro Tabárez"}]},{"text":"Sabía que llegarías hasta acá. Te estuve esperando.","uses":[{"file":"data/story.ts","line":1135,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Ya no me importa la lámpara ni la torre de Rivera. Esta noche se termina todo.","uses":[{"file":"data/story.ts","line":1135,"ctx":"sede_f1","who":"Bruma"}]},{"text":"El Dr. Díaz subió una máquina a la cúpula: la Máquina Pampero. Va a usar el eco del viento de tu compañero para llamar al Cardenal Azul.","uses":[{"file":"data/story.ts","line":1135,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Si el Cardenal vuelve y lo encierra, la niebla es nuestra para siempre. No voy a dejar que subas.","uses":[{"file":"data/story.ts","line":1135,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Perdí. Y me alegra, creo.","uses":[{"file":"data/story.ts","line":1139,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Nunca supe qué hacía con tantas máquinas. Dr. Díaz me dijo que era para proteger el clima.","uses":[{"file":"data/story.ts","line":1139,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Arriba están Brumario y Garúa. Ellos sí creen en él.","uses":[{"file":"data/story.ts","line":1139,"ctx":"sede_f1","who":"Bruma"}]},{"text":"Otra vez vos. En la Quebrada me ganaste con ayuda del viento.","uses":[{"file":"data/story.ts","line":1149,"ctx":"sede_f2","who":"Brumario"}]},{"text":"Acá no hay viento. Hay máquinas, y todas son nuestras.","uses":[{"file":"data/story.ts","line":1149,"ctx":"sede_f2","who":"Brumario"}]},{"text":"Dr. Díaz dice que el Cardenal es un animal, y que a un animal se lo encierra. Yo creo lo mismo.","uses":[{"file":"data/story.ts","line":1149,"ctx":"sede_f2","who":"Brumario"}]},{"text":"Perdí. Garúa, es tu turno.","uses":[{"file":"data/story.ts","line":1153,"ctx":"sede_f2","who":"Brumario"}]},{"text":"Pasaste por Minas, por la Represa y por acá. Sos terco.","uses":[{"file":"data/story.ts","line":1162,"ctx":"sede_f2b","who":"Garúa"}]},{"text":"La Máquina Pampero necesita un eco de viento vivo. Tu compañero lo tiene, y Dr. Díaz lo sabe desde el primer día.","uses":[{"file":"data/story.ts","line":1162,"ctx":"sede_f2b","who":"Garúa"}]},{"text":"No te lo voy a entregar. Ni vos ni él van a subir a la cúpula.","uses":[{"file":"data/story.ts","line":1162,"ctx":"sede_f2b","who":"Garúa"}]},{"text":"La Máquina Pampero no es lo que parece. Dr. Díaz no quiere vender niebla: quiere apagar el viento para siempre.","uses":[{"file":"data/story.ts","line":1166,"ctx":"sede_f2b","who":"Garúa"}]},{"text":"Lo supe tarde. Subí y detenelo.","uses":[{"file":"data/story.ts","line":1166,"ctx":"sede_f2b","who":"Garúa"}]},{"text":"Así que sos vos.","uses":[{"file":"data/story.ts","line":1174,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Soy Dr. Díaz, fundador del Proyecto Pampero. Lo que ustedes llaman Equipo PP.","uses":[{"file":"data/story.ts","line":1174,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Mi idea es simple: el clima es un recurso. Con las torres, la niebla se vende por días, por zonas, por contrato.","uses":[{"file":"data/story.ts","line":1174,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"El Cardenal Azul era un estorbo: cada vez que cruzaba el país, el pampero se llevaba mi niebla. En la Quebrada quise encerrarlo y me lo arruinaste.","uses":[{"file":"data/story.ts","line":1174,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Por eso esta máquina. Se alimenta del eco del viento que lleva tu compañero. Cuando lo llame, el Cardenal va a venir solo, y no va a volver a irse.","uses":[{"file":"data/story.ts","line":1174,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"¡{player}! Subí detrás tuyo, por la escalera de atrás.","uses":[{"file":"data/story.ts","line":1177,"ctx":"calima","who":"{rival}"}]},{"text":"Todo lo que le mandé al PP lo usó para armar esa máquina. Yo no sabía para qué era.","uses":[{"file":"data/story.ts","line":1177,"ctx":"calima","who":"{rival}"}]},{"text":"Si hay alguien que puede pararlo sos vos. Yo me quedo atrás: esta pelea es tuya.","uses":[{"file":"data/story.ts","line":1177,"ctx":"calima","who":"{rival}"}]},{"text":"Llegaste con las doce medallas. Se nota que no te asustan las torres.","uses":[{"file":"data/story.ts","line":1178,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Pero no vas a apagarme a mí.","uses":[{"file":"data/story.ts","line":1178,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"La Máquina Pampero tiembla. Las lámparas de la cúpula se apagan una por una.","uses":[{"file":"data/story.ts","line":1183,"ctx":"calima","who":""}]},{"text":"Un viento limpio entra por las ventanas rotas.","uses":[{"file":"data/story.ts","line":1183,"ctx":"calima","who":""}]},{"text":"El Cardenal Azul baja a la cúpula. Mira la máquina, mira a tu compañero y abre las alas.","uses":[{"file":"data/story.ts","line":1186,"ctx":"calima","who":""}]},{"text":"La Pluma Azul de tu mochila brilla con la misma luz.","uses":[{"file":"data/story.ts","line":1186,"ctx":"calima","who":""}]},{"text":"La máquina se apaga del todo. En la antena, el humo gris se va con el viento.","uses":[{"file":"data/story.ts","line":1189,"ctx":"calima","who":""}]},{"text":"Desde la cúpula se ve cómo el Cardenal Azul cruza el río, y detrás de él se limpia el cielo de Montevideo.","uses":[{"file":"data/story.ts","line":1191,"ctx":"calima","who":""}]},{"text":"Gané perdiendo… Ya no tengo equipo, ni dinero, ni torres.","uses":[{"file":"data/story.ts","line":1192,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Hacé lo que quieras. Pero el cielo nunca fue de nadie.","uses":[{"file":"data/story.ts","line":1192,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Díaz.","uses":[{"file":"data/story.ts","line":1195,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Llegué a tiempo para ver que no te quedó nada.","uses":[{"file":"data/story.ts","line":1195,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Tabárez. Siempre llegás cuando ya no hace falta.","uses":[{"file":"data/story.ts","line":1196,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Pero te lo dije en el Observatorio: el cielo no se queda quieto. Alguien lo iba a ordenar.","uses":[{"file":"data/story.ts","line":1196,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Ordenar no es vender. Eso nunca lo entendiste.","uses":[{"file":"data/story.ts","line":1197,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Hace veinte años firmamos juntos esa primera página del registro. Yo te creí un colega. Hoy te voy a acompañar a la comisaría: tenés mucho que contar.","uses":[{"file":"data/story.ts","line":1197,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"…Está bien.","uses":[{"file":"data/story.ts","line":1198,"ctx":"calima","who":"Dr. Díaz"}]},{"text":"Lo lograron, {player}. El Equipo PP está disuelto, y el Cardenal Azul vuelve a cruzar el país.","uses":[{"file":"data/story.ts","line":1202,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Con las doce medallas y el PP disuelto, la Liga te espera en el Estadio Centenario.","uses":[{"file":"data/story.ts","line":1202,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Dr. Díaz fue mi colega y no supe verlo venir. Gracias por corregir lo que yo no pude.","uses":[{"file":"data/story.ts","line":1202,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Y vos, sobrino, venite conmigo. Hablemos de lo que hiciste. Pero esta vez, juntos.","uses":[{"file":"data/story.ts","line":1203,"ctx":"calima","who":"Maestro Tabárez"}]},{"text":"Perdón, tío. Voy a arreglarlo. Pero antes, {player}: nos vemos en el Centenario. Ahí sí, sin trampa.","uses":[{"file":"data/story.ts","line":1204,"ctx":"calima","who":"{rival}"}]},{"text":"Cada vez que bajo por la ciclovía me siento joven.","uses":[{"file":"data/story.ts","line":1220,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Llegaste hasta el final. Pocos lo hacen.","uses":[{"file":"data/story.ts","line":1221,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Eso se premia. Tomá, un mate bien fuerte para el camino.","uses":[{"file":"data/story.ts","line":1221,"ctx":"gift_ciclovia","who":"Ciclista veterano"}]},{"text":"Del otro lado de la plaza se compra más barato. Pero acá, el café es mejor.","uses":[{"file":"data/story.ts","line":1227,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"Compro de un lado y vendo del otro.","uses":[{"file":"data/story.ts","line":1228,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"Tomá, un regalo para el viaje. Que no se te acaben las Ultraballs.","uses":[{"file":"data/story.ts","line":1228,"ctx":"gift_riv","who":"Comerciante"}]},{"text":"La represa es el orgullo de Salto. Y ahora, un problema.","uses":[{"file":"data/story.ts","line":1234,"ctx":"gift_sal","who":"Policía"}]},{"text":"Estoy de guardia, pero algo puedo hacer.","uses":[{"file":"data/story.ts","line":1235,"ctx":"gift_sal","who":"Policía"}]},{"text":"Tomá, que te sirve más que a mí.","uses":[{"file":"data/story.ts","line":1235,"ctx":"gift_sal","who":"Policía"}]},{"text":"El río siempre vuelve a su cauce.","uses":[{"file":"data/story.ts","line":1241,"ctx":"gift_pay","who":"Marinero"}]},{"text":"Hace años que navego esta costa.","uses":[{"file":"data/story.ts","line":1242,"ctx":"gift_pay","who":"Marinero"}]},{"text":"Llevate esto: no tiene mucho valor, pero sirve.","uses":[{"file":"data/story.ts","line":1242,"ctx":"gift_pay","who":"Marinero"}]},{"text":"El gimnasio de acá fue el más temido del litoral.","uses":[{"file":"data/story.ts","line":1248,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Mi abuelo me dijo que el frigorífico era cosa seria.","uses":[{"file":"data/story.ts","line":1249,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Tomá esto, para lo que venga.","uses":[{"file":"data/story.ts","line":1249,"ctx":"gift_frb","who":"Vecina"}]},{"text":"Desde Carmelo que te vengo siguiendo.","uses":[{"file":"data/story.ts","line":1256,"ctx":"rival_final","who":"{rival}"}]},{"text":"Esta es mi revancha. Voy con todo.","uses":[{"file":"data/story.ts","line":1256,"ctx":"rival_final","who":"{rival}"}]},{"text":"Andá. El Campeón te espera arriba.","uses":[{"file":"data/story.ts","line":1259,"ctx":"rival_final","who":"{rival}"}]},{"text":"Y ganale. Si no, quedo mal yo también.","uses":[{"file":"data/story.ts","line":1259,"ctx":"rival_final","who":"{rival}"},{"file":"data/story.ts","line":1262,"ctx":"rival_final","who":"{rival}"}]},{"text":"Esta vez gané yo, pero el Campeón es otra cosa. Andá, te espera arriba.","uses":[{"file":"data/story.ts","line":1262,"ctx":"rival_final","who":"{rival}"}]},{"text":"Sos imparable. Volvé cuando quieras.","uses":[{"file":"data/story.ts","line":1279,"ctx":"champion","who":"Obdulio"}]},{"text":"Felicitaciones, {player}. Desde hoy sos el nuevo Campeón de la Liga Oriental.","uses":[{"file":"data/story.ts","line":1282,"ctx":"champion","who":"Obdulio"}]},{"text":"Tu nombre va a quedar en el Salón de la Fama del Centenario.","uses":[{"file":"data/story.ts","line":1282,"ctx":"champion","who":"Obdulio"}]},{"text":"Algunas semanas después, en Carmelo.","uses":[{"file":"data/story.ts","line":1291,"ctx":"champion","who":""}]},{"text":"Se habla de criaturas legendarias avistadas en el país:","uses":[{"file":"data/story.ts","line":1291,"ctx":"champion","who":""}]},{"text":"un viento helado en la Quebrada, un canto en la costa de Punta del Este.","uses":[{"file":"data/story.ts","line":1291,"ctx":"champion","who":""}]},{"text":"Tu aventura continúa.","uses":[{"file":"data/story.ts","line":1291,"ctx":"champion","who":""}]},{"text":"Los animales ya se fueron del camino.","uses":[{"file":"data/story.ts","line":1296,"ctx":"route_riddle","who":""}]},{"text":"Yo sigo con mi trabajo: alguien tiene que cuidar el paso.","uses":[{"file":"data/story.ts","line":1296,"ctx":"route_riddle","who":""}]},{"text":"Estos animales no se van a mover solos.","uses":[{"file":"data/story.ts","line":1297,"ctx":"route_riddle","who":""}]},{"text":"No es eso. Pensalo y volvé a intentar.","uses":[{"file":"data/story.ts","line":1301,"ctx":"route_riddle","who":""}]},{"text":"Correcto. Con eso alcanza: los animales se apartan del camino.","uses":[{"file":"data/story.ts","line":1304,"ctx":"route_riddle","who":""}]},{"text":"La tranquera ya está abierta.","uses":[{"file":"data/story.ts","line":1310,"ctx":"route_palanca","who":""}]},{"text":"Soltaste la palanca. Los cerrojos vuelven a su lugar.","uses":[{"file":"data/story.ts","line":1312,"ctx":"route_palanca","who":""}]},{"text":"Se oye el último cerrojo. La tranquera se abre sola.","uses":[{"file":"data/story.ts","line":1319,"ctx":"route_palanca","who":""}]},{"text":"Algo hizo un ruido seco. Los cerrojos volvieron a su lugar.","uses":[{"file":"data/story.ts","line":1325,"ctx":"route_palanca","who":""}]},{"text":"PS","uses":[{"file":"game/battle-scene.ts","line":275,"ctx":"box","who":""},{"file":"game/menus.ts","line":33,"ctx":"hpBar","who":""},{"file":"game/menus.ts","line":248,"ctx":"render","who":""}]},{"text":"¡No te quedan criaturas en condiciones de pelear!","uses":[{"file":"game/battle-scene.ts","line":431,"ctx":"runBattle","who":""}]},{"text":"…","uses":[{"file":"game/battle-scene.ts","line":431,"ctx":"runBattle","who":""},{"file":"game/world.ts","line":1064,"ctx":"blackout","who":""}]},{"text":"Todo se pone gris…","uses":[{"file":"game/battle-scene.ts","line":431,"ctx":"runBattle","who":""}]},{"text":"Es tu primer combate. Te voy a ir explicando cómo se pelea.","uses":[{"file":"game/battle-scene.ts","line":584,"ctx":"tutoIntro","who":""}]},{"text":"Así se ataca. Cuando los PS de la criatura rival llegan a cero, queda fuera de combate.","uses":[{"file":"game/battle-scene.ts","line":593,"ctx":"tutoAfterTurn","who":""}]},{"text":"En «Mochila» se usan los Mates para curar y las Pokeballs para atrapar criaturas salvajes. «Equipo» cambia de criatura y «Huir» escapa de las salvajes.","uses":[{"file":"game/battle-scene.ts","line":593,"ctx":"tutoAfterTurn","who":""}]},{"text":"Movimiento nuevo","uses":[{"file":"game/battle-scene.ts","line":644,"ctx":"chooseMove","who":""}]},{"text":"Poder","uses":[{"file":"game/battle-scene.ts","line":669,"ctx":"show","who":""}]},{"text":"Precisión","uses":[{"file":"game/battle-scene.ts","line":670,"ctx":"show","who":""}]},{"text":"¿Cuál movimiento debería olvidar?","uses":[{"file":"game/battle-scene.ts","line":1061,"ctx":"learnFlow","who":""}]},{"text":"▶▶","uses":[{"file":"game/hud.ts","line":37,"ctx":"mountHud","who":""}]},{"text":"x2","uses":[{"file":"game/hud.ts","line":37,"ctx":"mountHud","who":""}]},{"text":"El hornero no te obedece todavía. Hace falta la Medalla Florida.","uses":[{"file":"game/menus.ts","line":106,"ctx":"pickFlight","who":""}]},{"text":"Acá adentro no se puede usar.","uses":[{"file":"game/menus.ts","line":107,"ctx":"pickFlight","who":""}]},{"text":"Todavía no conocés ninguna ciudad adonde volar.","uses":[{"file":"game/menus.ts","line":109,"ctx":"pickFlight","who":""}]},{"text":"Ataques","uses":[{"file":"game/menus.ts","line":253,"ctx":"render","who":""}]},{"text":"Mochila","uses":[{"file":"game/menus.ts","line":310,"ctx":"openBag","who":""}]},{"text":"¡No es momento de usar eso!","uses":[{"file":"game/menus.ts","line":344,"ctx":"use","who":""},{"file":"game/menus.ts","line":349,"ctx":"use","who":""}]},{"text":"¡No hay lugar para más criaturas!","uses":[{"file":"game/menus.ts","line":346,"ctx":"use","who":""}]},{"text":"Se equipa fuera de combate.","uses":[{"file":"game/menus.ts","line":350,"ctx":"use","who":""}]},{"text":"Mejor usala fuera de combate.","uses":[{"file":"game/menus.ts","line":351,"ctx":"use","who":""},{"file":"game/menus.ts","line":352,"ctx":"use","who":""}]},{"text":"No tendría ningún efecto.","uses":[{"file":"game/menus.ts","line":366,"ctx":"use","who":""},{"file":"game/menus.ts","line":428,"ctx":"onUse","who":""},{"file":"game/menus.ts","line":450,"ctx":"useInField","who":""}]},{"text":"¡Eso es muy importante para tirarlo!","uses":[{"file":"game/menus.ts","line":371,"ctx":"use","who":""}]},{"text":"¡Las Pokeballs se usan en combate!","uses":[{"file":"game/menus.ts","line":413,"ctx":"useInField","who":""}]},{"text":"Solo se puede usar en combate.","uses":[{"file":"game/menus.ts","line":420,"ctx":"useInField","who":""}]},{"text":"PokeDex","uses":[{"file":"game/menus.ts","line":487,"ctx":"openDex","who":""},{"file":"game/menus.ts","line":783,"ctx":"openCard","who":""}]},{"text":"Ninguna criatura coincide con la búsqueda.","uses":[{"file":"game/menus.ts","line":494,"ctx":"show","who":""}]},{"text":"Sin datos. Todavía no viste a esta criatura.","uses":[{"file":"game/menus.ts","line":500,"ctx":"show","who":""}]},{"text":"Departamento","uses":[{"file":"game/menus.ts","line":686,"ctx":"openMap","who":""}]},{"text":"Zona","uses":[{"file":"game/menus.ts","line":687,"ctx":"openMap","who":""}]},{"text":"Criaturas que aparecen","uses":[{"file":"game/menus.ts","line":688,"ctx":"openMap","who":""}]},{"text":"Mapa","uses":[{"file":"game/menus.ts","line":692,"ctx":"openMap","who":""}]},{"text":"???","uses":[{"file":"game/menus.ts","line":705,"ctx":"none","who":""}]},{"text":"Ninguna","uses":[{"file":"game/menus.ts","line":726,"ctx":"show","who":""}]},{"text":"Ficha de Entrenador","uses":[{"file":"game/menus.ts","line":778,"ctx":"openCard","who":""}]},{"text":"Nombre","uses":[{"file":"game/menus.ts","line":781,"ctx":"openCard","who":""}]},{"text":"Dinero","uses":[{"file":"game/menus.ts","line":782,"ctx":"openCard","who":""}]},{"text":"Hoy","uses":[{"file":"game/menus.ts","line":784,"ctx":"openCard","who":""}]},{"text":"Hora","uses":[{"file":"game/menus.ts","line":785,"ctx":"openCard","who":""}]},{"text":"Tiempo","uses":[{"file":"game/menus.ts","line":786,"ctx":"openCard","who":""}]},{"text":"Victorias","uses":[{"file":"game/menus.ts","line":787,"ctx":"openCard","who":""}]},{"text":"Inicio","uses":[{"file":"game/menus.ts","line":788,"ctx":"openCard","who":""}]},{"text":"Medallas","uses":[{"file":"game/menus.ts","line":792,"ctx":"openCard","who":""}]},{"text":"★ Campeón de la Liga Oriental ★","uses":[{"file":"game/menus.ts","line":794,"ctx":"openCard","who":""}]},{"text":"Medidor de Niebla","uses":[{"file":"game/menus.ts","line":817,"ctx":"openFogMeter","who":""}]},{"text":"de toxicidad en el aire","uses":[{"file":"game/menus.ts","line":819,"ctx":"openFogMeter","who":""}]},{"text":"Todavía no cerraste ninguna.","uses":[{"file":"game/menus.ts","line":827,"ctx":"openFogMeter","who":""}]},{"text":"Máquinas de niebla sueltas","uses":[{"file":"game/menus.ts","line":830,"ctx":"openFogMeter","who":""}]},{"text":"Sonido","uses":[{"file":"game/menus.ts","line":855,"ctx":"openSound","who":""}]},{"text":"Opciones","uses":[{"file":"game/menus.ts","line":893,"ctx":"openOptions","who":""}]},{"text":"Controles","uses":[{"file":"game/menus.ts","line":931,"ctx":"openControls","who":""}]},{"text":"¿En qué ranura querés guardar?","uses":[{"file":"game/menus.ts","line":948,"ctx":"openSave","who":""}]},{"text":"No se pudo guardar.","uses":[{"file":"game/menus.ts","line":963,"ctx":"openSave","who":""}]},{"text":"¿Algo más?","uses":[{"file":"game/menus.ts","line":976,"ctx":"openShop","who":"Almacenero"}]},{"text":"¡Gracias! ¡Volvé pronto!","uses":[{"file":"game/menus.ts","line":978,"ctx":"openShop","who":"Almacenero"}]},{"text":"↑↓ ±1 · ←→ ±10","uses":[{"file":"game/menus.ts","line":988,"ctx":"qtyPicker","who":""}]},{"text":"No te alcanza la plata.","uses":[{"file":"game/menus.ts","line":1012,"ctx":"buyFlow","who":"Almacenero"},{"file":"game/menus.ts","line":1016,"ctx":"buyFlow","who":""}]},{"text":"¡Acá tenés! Gracias.","uses":[{"file":"game/menus.ts","line":1019,"ctx":"buyFlow","who":"Almacenero"}]},{"text":"Por comprar 10, te regalo una Superball.","uses":[{"file":"game/menus.ts","line":1022,"ctx":"buyFlow","who":"Almacenero"}]},{"text":"No tenés nada para vender.","uses":[{"file":"game/menus.ts","line":1031,"ctx":"sellFlow","who":"Almacenero"}]},{"text":"Encendiste la computadora. Se conectó a la Caja de Criaturas.","uses":[{"file":"game/menus.ts","line":1060,"ctx":"openPC","who":""}]},{"text":"La Caja está vacía.","uses":[{"file":"game/menus.ts","line":1065,"ctx":"openPC","who":""}]},{"text":"Tu equipo está lleno.","uses":[{"file":"game/menus.ts","line":1066,"ctx":"openPC","who":""}]},{"text":"¡No podés quedarte sin criaturas!","uses":[{"file":"game/menus.ts","line":1074,"ctx":"openPC","who":""}]},{"text":"Necesitás al menos una criatura sana en el equipo.","uses":[{"file":"game/menus.ts","line":1078,"ctx":"openPC","who":""}]},{"text":"Bienvenido al mundo de Poke Uruguay.","uses":[{"file":"game/scenes.ts","line":306,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Soy el Maestro Tabárez. Dirigí a la selección durante años y hoy me dedico a estudiar a las criaturas de este país.","uses":[{"file":"game/scenes.ts","line":306,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"En este país conviven personas y criaturas.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Algunas nadan en el Río de la Plata, otras recorren las praderas o vuelan sobre las sierras.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"La gente trabaja con ellas, las entrena y, a veces, combate con ellas.","uses":[{"file":"game/scenes.ts","line":309,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Ahora hablemos de vos. ¿Cómo te presentás?","uses":[{"file":"game/scenes.ts","line":312,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Así que te llamás {player}. Un gusto.","uses":[{"file":"game/scenes.ts","line":319,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Este es mi nieto. Compite con vos desde que eran niños. ¿Cómo se llamaba?","uses":[{"file":"game/scenes.ts","line":320,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Claro, {rival}. Cómo me pude olvidar.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"{player}, tu propia historia está por empezar.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"Un camino largo te espera por todo el Uruguay. Vamos.","uses":[{"file":"game/scenes.ts","line":323,"ctx":"newGameIntro","who":"Maestro Tabárez"}]},{"text":"★ Campeón","uses":[{"file":"game/scenes.ts","line":429,"ctx":"slotCard","who":""}]},{"text":"Atajos","uses":[{"file":"game/sidebar.ts","line":71,"ctx":"mountSidebar","who":""}]},{"text":"▾","uses":[{"file":"game/sidebar.ts","line":71,"ctx":"mountSidebar","who":""},{"file":"game/sidebar.ts","line":107,"ctx":"mountSidebar","who":""}]},{"text":"Tu equipo","uses":[{"file":"game/sidebar.ts","line":106,"ctx":"mountSidebar","who":""}]},{"text":"▼","uses":[{"file":"game/ui.ts","line":40,"ctx":"mountUI","who":""}]},{"text":"‹ Volver","uses":[{"file":"game/ui.ts","line":158,"ctx":"choose","who":""}]},{"text":"Listo","uses":[{"file":"game/ui.ts","line":243,"ctx":"textInput","who":""}]},{"text":"¡Ding, dong! Se terminó el tiempo del concurso.","uses":[{"file":"game/world.ts","line":228,"ctx":"safariClock","who":""}]},{"text":"Los guardaparques te acompañan de vuelta con los jueces.","uses":[{"file":"game/world.ts","line":228,"ctx":"safariClock","who":""}]},{"text":"¡Ding, dong! Se terminó el tiempo contratado.","uses":[{"file":"game/world.ts","line":229,"ctx":"safariClock","who":""}]},{"text":"Los guardias del Safari te acompañan hasta la salida.","uses":[{"file":"game/world.ts","line":229,"ctx":"safariClock","who":""}]},{"text":"El efecto del Repelente se terminó.","uses":[{"file":"game/world.ts","line":554,"ctx":"onStep","who":""}]},{"text":"Un mojón de la ruta, con el kilómetro pintado en rojo.","uses":[{"file":"game/world.ts","line":798,"ctx":"interact","who":""}]},{"text":"Quien pasa a su lado queda anotado en el punto de control: si las criaturas caen, se despierta acá con la salud completa.","uses":[{"file":"game/world.ts","line":798,"ctx":"interact","who":""}]},{"text":"No se puede curar a nadie en este lugar. Para eso hace falta una Policlínica.","uses":[{"file":"game/world.ts","line":798,"ctx":"interact","who":""}]},{"text":"Es la cama de otra persona. Mejor no tocarla.","uses":[{"file":"game/world.ts","line":817,"ctx":"sleepInBed","who":""}]},{"text":"Un zarzal espeso y espinoso. Con algo filoso se podría abrir paso.","uses":[{"file":"game/world.ts","line":947,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. Para usar el Machete hace falta la Medalla de Fray Bentos.","uses":[{"file":"game/world.ts","line":948,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. El Machete no alcanza todavía: hace falta la Medalla Salto.","uses":[{"file":"game/world.ts","line":949,"ctx":"cutBush","who":""}]},{"text":"Un zarzal espeso. Con el Machete se puede abrir paso.","uses":[{"file":"game/world.ts","line":950,"ctx":"cutBush","who":""}]},{"text":"¡Despejaste el camino!","uses":[{"file":"game/world.ts","line":956,"ctx":"cutBush","who":""}]},{"text":"El agua está turbia. Sin una caña, mejor no meterse.","uses":[{"file":"game/world.ts","line":1007,"ctx":"fish","who":""}]},{"text":"Tus criaturas están debilitadas. Mejor no arriesgarse.","uses":[{"file":"game/world.ts","line":1009,"ctx":"fish","who":""}]},{"text":"Se terminó el tiempo del concurso. Llevale tu mejor pez al juez.","uses":[{"file":"game/world.ts","line":1011,"ctx":"fish","who":""}]},{"text":"Lanzaste la caña al agua…","uses":[{"file":"game/world.ts","line":1018,"ctx":"fish","who":""}]},{"text":"No picó nada. Probá de nuevo.","uses":[{"file":"game/world.ts","line":1025,"ctx":"fish","who":""}]},{"text":"¡Algo picó!","uses":[{"file":"game/world.ts","line":1030,"ctx":"fish","who":""}]},{"text":"Llegó tarde: se acabó el tiempo y la línea quedó floja.","uses":[{"file":"game/world.ts","line":1038,"ctx":"fish","who":""}]},{"text":"Volviste a descansar para recuperarte.","uses":[{"file":"game/world.ts","line":1083,"ctx":"runScript","who":""}]},{"text":"¿Eh? ¡El Huevo se está moviendo!","uses":[{"file":"game/world.ts","line":1139,"ctx":"eggHatch","who":""}]},{"text":"Necesitás otra criatura en condiciones para seguir viaje.","uses":[{"file":"game/world.ts","line":1170,"ctx":"tradeCreature","who":""},{"file":"game/world.ts","line":1186,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1190,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1242,"ctx":"criadero","who":""},{"file":"game/world.ts","line":1246,"ctx":"criadero","who":""}]},{"text":"Bienvenido a la guardería. Cuido a tus criaturas mientras caminás: ganan experiencia con cada paso que das.","uses":[{"file":"game/world.ts","line":1184,"ctx":"daycare","who":""}]},{"text":"Dejala y volvé cuando quieras. Retirarla cuesta un poco más cuanto más haya crecido.","uses":[{"file":"game/world.ts","line":1184,"ctx":"daycare","who":""}]},{"text":"Tu equipo está completo. Dejá lugar y volvé a buscarla.","uses":[{"file":"game/world.ts","line":1204,"ctx":"daycare","who":""},{"file":"game/world.ts","line":1260,"ctx":"criadero","who":""}]},{"text":"Bienvenido al Criadero Los Teros. Acá las criaturas crecen con aire libre y buen pasto.","uses":[{"file":"game/world.ts","line":1234,"ctx":"criadero","who":""}]},{"text":"Cuando quieras. Acá las cuidamos bien.","uses":[{"file":"game/world.ts","line":1239,"ctx":"criadero","who":""}]},{"text":"Los corrales están llenos. Retirá a alguna primero.","uses":[{"file":"game/world.ts","line":1241,"ctx":"criadero","who":""}]}];
